export default "lse:\\n        logger.info(\\\"Not enough delta content to analyze pattern\\\")\\n\\n    if openai_actual_tool_events:\\n        logger.info(\\\"OpenAI tool call example:\\\")\\n        logger.debug(f\\\"  {json.dumps(openai_actual_tool_events[0], indent=2)}\\\")\\n\\n    if our_function_events:\\n        logger.info(\\\"Our function call example:\\\")\\n        logger.debug(f\\\"  {json.dumps(our_function_events[0], indent=2)}\\\")\\n\\n    # === Validation ===\\n\\n    # Basic validation\\n    assert len(openai_parsed) > 0, \\\"No OpenAI events received\\\"\\n    assert len(our_parsed) > 0, \\\"No events from our API\\\"\\n\\n    # Check if both APIs produced function call events\\n    if len(openai_actual_tool_events) > 0:\\n        logger.success(\\\"\u2705 OpenAI produced function call events\\\")\\n        if len(our_function_events) > 0:\\n            logger.success(\\\"\u2705 Our API also produced function call events\\\")\\n            logger.success(\\\"\u2705 Both APIs support function call streaming\\\")\\n        else:\\n            logger.error(\\\"\u274c Our API did not produce function call events\\\")\\n            pytest.fail(\\\"Our API should produce function call events when OpenAI does\\\")\\n    else:\\n        logger.info(\\\"No function calls were made by OpenAI\\\")\\n\\n    logger.info(\\\"\ud83d\udcca Test Summary:\\\")\\n    logger.info(f\\\"  OpenAI events: {len(openai_parsed)}\\\")\\n    logger.info(f\\\"  Our events: {len(our_parsed)}\\\")\\n    logger.info(f\\\"  OpenAI function events: {len(openai_actual_tool_events)}\\\")\\n    logger.info(f\\\"  Our function events: {len(our_function_events)}\\\")\\n    compatibility_result = (\\n        \\\"\u2705 PASS\\\" if len(our_function_events) > 0 or len(openai_actual_tool_events) == 0 else \\\"\u274c FAIL\\\"\\n    )\\n    logger.info(f\\\"  Format compatibility: {compatibility_result}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/integration/test_projects_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3b5f77fda6814c6d62fc32a7075daed30a00adfa6057b3e60f3178b59c6d1371\",\"content\":\"\\\"\\\"\\\"Integration tests for project creation logic.\\n\\nThese tests verify the project creation endpoint with minimal mocking,\\nfocusing on real database interactions and business logic.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock, patch\\nfrom uuid import UUID\\n\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment_provider_account.model import (\\n    DeploymentProviderAccount,\\n    DeploymentProviderKey,\\n)\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\nfrom langflow.services.deps import session_scope\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\n\\n\\nasync def _attach_deployment_to_flow(*, user_id: UUID, flow_id: UUID, project_id: UUID) -> None:\\n    async with session_scope() as session:\\n        provider = DeploymentProviderAccount(\\n            user_id=user_id,\\n            name=f\\\"integration-provider-{flow_id.hex[:8]}\\\",\\n            provider_tenant_id=\\\"tenant-1\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_url=f\\\"https://integration-{flow_id.hex[:8]}.example.com\\\",\\n            api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n        )\\n        session.add(provider)\\n        await session.flush()\\n\\n        deployment = Deployment(\\n            user_id=user_id,\\n            project_id=project_id,\\n            deployment_provider_account_id=provider.id,\\n            resource_key=f\\\"integration-rk-{flow_id.hex[:8]}\\\",\\n            display_name=f\\\"integration-deployment-{flow_id.hex[:8]}\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        session.add(deployment)\\n        await session.flush()\\n\\n        flow_version = FlowVersion(\\n            flow_id=flow_id,\\n            user_id=user_id,\\n            version_number=1,\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n        session.add(flow_version)\\n        await session.flush()\\n\\n        attachment = FlowVersionDeploymentAttachment(\\n            user_id=user_id,\\n            flow_version_id=flow_version.id,\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=f\\\"integration-snapshot-{flow_id.hex[:8]}\\\",\\n        )\\n        session.add(attachment)\\n        await session.commit()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_project_authentication_settings(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Integration test: Project authentication settings configuration.\\\"\\\"\\\"\\n    # Scenario 1: AUTO_LOGIN disabled -> API key auth\\n    with patch(\\\"langflow.api.v1.projects.get_settings_service\\\") as mock_get_settings:\\n        mock_service = MagicMock()\\n        mock_service.settings.add_projects_to_mcp_servers = False\\n        mock_service.auth_settings.AUTO_LOGIN = False\\n        mock_get_settings.return_value = mock_service\\n\\n        with patch(\\\"langflow.api.v1.projects.encrypt_auth_settings\\\") as mock_encrypt:\\n            mock_encrypt.return_value = {\\\"encrypted\\\": \\\"apikey_auth\\\"}\\n\\n            response = await client.post(\\n                \\\"api/v1/projects/\\\",\\n                json={\\\"name\\\": \\\"Auth Test 1\\\", \\\"description\\\": \\\"\\\", \\\"flows_list\\\": [], \\\"components_list\\\": []},\\n                headers=logged_in_headers,\\n            )\\n\\n            assert response.status_code == status.HTTP_201_CREATED\\n            project = response.json()\\n\\n            # Verify encrypt was called with apikey auth type\\n            mock_encrypt.assert_called_once_with({\\\"auth_type\\\": \\\"apikey\\\"})\\n            assert project[\\\"name\\\"] == \\\"Auth Test 1\\\"\\n            assert \\\"id\\\" in project\\n\\n    # Scenario 2: AUTO_LOGIN enabled -> no auth\\n    with patch(\\\"langflow.api.v1.projects.get_settings_service\\\") as mock_get_settings:\\n        mock_service = MagicMock()\\n        mock_service.settings.add_projects_to_mcp_servers = False\\n        mock_service.auth_settings.AUTO_LOGIN = True\\n        mock_get_settings.return_value = mock_service\\n\\n        response = await client.post(\\n            \\\"api/v1/projects/\\\",\\n            json={\\\"name\\\": \\\"Auth Test 2\\\", \\\"description\\\": \\\"\\\", \\\"flows_list\\\": [], \\\"components_list\\\": []},\\n            headers=logged_in_headers,\\n        )\\n\\n        assert response.status_code == status.HTTP_201_CREATED\\n        project = response.json()\\n        assert project[\\\"name\\\"] == \\\"Auth Test 2\\\"\\n        assert \\\"id\\\" in project\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_project_blocks_moving_deployed_flow(client: AsyncClient, logged_in_headers, active_user):\\n    flow_resp = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": \\\"integration-deployed-flow\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n        headers=logged_in_headers,\\n    )\\n    assert flow_resp.status_code == status.HTTP_201_CREATED\\n\\n    payload = flow_resp.json()\\n    flow_id = UUID(payload[\\\"id\\\"])\\n    source_project_id = UUID(payload[\\\"folder_id\\\"])\\n    await _attach_deployment_to_flow(\\n        user_id=active_user.id,\\n        flow_id=flow_id,\\n        project_id=source_project_id,\\n    )\\n\\n    create_resp = await client.post(\\n        \\\"api/v1/projects/\\\",\\n        json={\\\"name\\\": \\\"integration-target-project\\\", \\\"flows_list\\\": [str(flow_id)], \\\"components_list\\\": []},\\n        headers=logged_in_headers,\\n    )\\n    assert create_resp.status_code == status.HTTP_409_CONFLICT\\n    assert \\\"cannot be moved to another project\\\" in create_resp.json()[\\\"detail\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/integration/test_telemetry_splitting_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"31725e3079e54c6186125a49b87e27d24871c8775225fe6d6451858c4bef979b\",\"content\":\"\\\"\\\"\\\"Integration tests for telemetry service splitting.\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom langflow.services.telemetry.schema import ComponentInputsPayload\\nfrom langflow.services.telemetry.service import TelemetryService\\n\\n\\n@pytest.mark.asyncio\\nasync def test_service_splits_large_payload(mock_settings_service):\\n    \\\"\\\"\\\"Test that service splits large payload and queues multiple chunks.\\\"\\\"\\\"\\n    service = TelemetryService(mock_settings_service)\\n\\n    # Create large payload with dict[str, Any] type\\n    large_inputs = {f\\\"input_{i}\\\": \\\"x\\\" * 100 for i in range(50)}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=large_inputs,\\n    )\\n\\n    # Track queued events\\n    queued_events = []\\n\\n    async def mock_queue_event(event):\\n        queued_events.append(event)\\n\\n    service._queue_event = mock_queue_event\\n\\n    # Log the payload\\n    await service.log_package_component_inputs(payload)\\n\\n    # Should have queued multiple chunks\\n    assert len(queued_events) > 1\\n\\n    # Each queued event should be a tuple (func, payload, path)\\n    for event in queued_events:\\n        assert isinstance(event, tuple)\\n        assert len(event) == 3\\n\\n\\n@pytest.mark.asyncio\\nasync def test_service_no_split_for_small_payload(mock_settings_service):\\n    \\\"\\\"\\\"Test that service doesn't split small payload.\\\"\\\"\\\"\\n    service = TelemetryService(mock_settings_service)\\n\\n    # Create small payload with dict[str, Any] type\\n    small_inputs = {\\\"input1\\\": \\\"value1\\\"}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=small_inputs,\\n    )\\n\\n    # Track queued events\\n    queued_events = []\\n\\n    async def mock_queue_event(event):\\n        queued_events.append(event)\\n\\n    service._queue_event = mock_queue_event\\n\\n    # Log the payload\\n    await service.log_package_component_inputs(payload)\\n\\n    # Should have queued only one event\\n    assert len(queued_events) == 1\\n\\n\\n@pytest.fixture\\ndef mock_settings_service():\\n    \\\"\\\"\\\"Mock settings service for testing.\\\"\\\"\\\"\\n    settings_service = MagicMock()\\n    settings_service.settings.telemetry_base_url = \\\"https://api.scarf.sh/v1/pixel\\\"\\n    settings_service.settings.do_not_track = False\\n    settings_service.settings.prometheus_enabled = False\\n    settings_service.auth_settings.AUTO_LOGIN = False\\n\\n    return settings_service\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/integration/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"421dd3d664c8747529b6130cd4886d4d1a22493a1d6d2ed983fdb016ca55b3af\",\"content\":\"import dataclasses\\nimport os\\nimport uuid\\nfrom typing import Any\\n\\nimport pytest\\nimport requests\\nfrom lfx.custom import Component\\nfrom lfx.custom.eval import eval_custom_component_code\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.graph import Graph\\nfrom lfx.processing.process import run_graph_internal\\nfrom lfx.schema.schema import InputValueRequest\\n\\n\\ndef check_env_vars(*env_vars):\\n    \\\"\\\"\\\"Check if all specified environment variables are set.\\n\\n    Args:\\n    *env_vars (str): The environment variables to check.\\n\\n    Returns:\\n    bool: True if all environment variables are set, False otherwise.\\n    \\\"\\\"\\\"\\n    return all(os.getenv(var) for var in env_vars)\\n\\n\\ndef valid_nvidia_vectorize_region(api_endpoint: str) -> bool:\\n    \\\"\\\"\\\"Check if the specified region is valid.\\n\\n    Args:\\n        api_endpoint: The API endpoint to check.\\n\\n    Returns:\\n        True if the region contains hosted nvidia models, False otherwise.\\n    \\\"\\\"\\\"\\n    try:\\n        from astrapy.admin import parse_api_endpoint\\n    except ImportError as e:\\n        msg = \\\"Could not import astrapy package. Please install it with `uv pip install astrapy`.\\\"\\n        raise ImportError(msg) from e\\n    parsed_endpoint = parse_api_endpoint(api_endpoint)\\n    if not parsed_endpoint:\\n        msg = \\\"Invalid ASTRA_DB_API_ENDPOINT\\\"\\n        raise ValueError(msg)\\n    return parsed_endpoint.region == \\\"us-east-2\\\"\\n\\n\\nclass MockEmbeddings(Embeddings):\\n    def __init__(self):\\n        self.embedded_documents = None\\n        self.embedded_query = None\\n\\n    @staticmethod\\n    def mock_embedding(text: str):\\n        return [len(text) / 2, len(text) / 5, len(text) / 10]\\n\\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\\n        self.embedded_documents = texts\\n        return [self.mock_embedding(text) for text in texts]\\n\\n    def embed_query(self, text: str) -> list[float]:\\n        self.embedded_query = text\\n        return self.mock_embedding(text)\\n\\n\\n@dataclasses.dataclass\\nclass JSONFlow:\\n    json: dict\\n\\n    def get_components_by_type(self, component_type):\\n        result = [node[\\\"id\\\"] for node in self.json[\\\"data\\\"][\\\"nodes\\\"] if node[\\\"data\\\"][\\\"type\\\"] == component_type]\\n        if not result:\\n            msg = (\\n                f\\\"Component of type {component_type} not found, \\\"\\n                f\\\"available types: {', '.join({node['data']['type'] for node in self.json['data']['nodes']})}\\\"\\n            )\\n            raise ValueError(msg)\\n        return result\\n\\n    def get_component_by_type(self, component_type):\\n        components = self.get_components_by_type(component_type)\\n        if len(components) > 1:\\n            msg = f\\\"Multiple components of type {component_type} found\\\"\\n            raise ValueError(msg)\\n        return components[0]\\n\\n    def set_value(self, component_id, key, value):\\n        done = False\\n        for node in self.json[\\\"data\\\"][\\\"nodes\\\"]:\\n            if node[\\\"id\\\"] == component_id:\\n                if key not in node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]:\\n                    msg = f\\\"Component {component_id} does not have input {key}\\\"\\n                    raise ValueError(msg)\\n                node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][key][\\\"value\\\"] = value\\n                node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][key][\\\"load_from_db\\\"] = False\\n                done = True\\n                break\\n        if not done:\\n            msg = f\\\"Component {component_id} not found\\\"\\n            raise ValueError(msg)\\n\\n\\ndef download_flow_from_github(name: str, version: str) -> JSONFlow:\\n    response = requests.get(\\n        f\\\"https://raw.githubusercontent.com/langflow-ai/langflow/v{version}/src/backend/base/langflow/initial_setup/starter_projects/{name}.json\\\",\\n        timeout=10,\\n    )\\n    response.raise_for_status()\\n    as_json = response.json()\\n    return JSONFlow(json=as_json)\\n\\n\\ndef download_component_from_github(module: str, file_name: str, version: str) -> Component:\\n    version_string = f\\\"v{version}\\\" if version != \\\"main\\\" else version\\n    response = requests.get(\\n        f\\\"https://raw.githubusercontent.com/langflow-ai/langflow/{version_string}/src/backend/base/langflow/components/{module}/{file_name}.py\\\",\\n        timeout=10,\\n    )\\n    response.raise_for_status()\\n    return Component(_code=response.text)\\n\\n\\nasync def run_json_flow(\\n    json_flow: JSONFlow, run_input: Any | None = None, session_id: str | None = None\\n) -> dict[str, Any]:\\n    graph = Graph.from_payload(json_flow.json)\\n    return await run_flow(graph, run_input, session_id)\\n\\n\\nasync def run_flow(graph: Graph, run_input: Any | None = None, session_id: str | None = None) -> dict[str, Any]:\\n    graph.prepare()\\n    graph_run_inputs = [InputValueRequest(input_value=run_input, type=\\\"chat\\\")] if run_input else []\\n\\n    flow_id = str(uuid.uuid4())\\n\\n    results, _ = await run_graph_internal(graph, flow_id, session_id=session_id, inputs=graph_run_inputs)\\n    outputs = {}\\n    for r in results:\\n        for out in r.outputs:\\n            outputs |= out.results\\n    return outputs\\n\\n\\n@dataclasses.dataclass\\nclass ComponentInputHandle:\\n    clazz: type\\n    inputs: dict\\n    output_name: str\\n\\n\\nasync def run_single_component(\\n    clazz: type,\\n    inputs: dict | None = None,\\n    run_input: Any | None = None,\\n    session_id: str | None = None,\\n    input_type: str | None = \\\"chat\\\",\\n) -> dict[str, Any]:\\n    user_id = str(uuid.uuid4())\\n    flow_id = str(uuid.uuid4())\\n    graph = Graph(user_id=user_id, flow_id=flow_id)\\n\\n    def _add_component(clazz: type, inputs: dict | None = None) -> str:\\n        raw_inputs = {}\\n        if inputs:\\n            for key, value in inputs.items():\\n                if not isinstance(value, ComponentInputHandle):\\n                    raw_inputs[key] = value\\n                if isinstance(value, Component):\\n                    msg = \\\"Component inputs must be wrapped in ComponentInputHandle\\\"\\n                    raise TypeError(msg)\\n        component = clazz(**raw_inputs, _user_id=user_id)\\n        component_id = graph.add_component(component)\\n        if inputs:\\n            for input_name, handle in inputs.items():\\n                if isinstance(handle, ComponentInputHandle):\\n                    handle_component_id = _add_component(handle.clazz, handle.inputs)\\n                    graph.add_component_edge(handle_component_id, (handle.output_name, input_name), component_id)\\n        return component_id\\n\\n    component_id = _add_component(clazz, inputs)\\n    graph.prepare()\\n    graph_run_inputs = [InputValueRequest(input_value=run_input, type=input_type)] if run_input else []\\n\\n    _, _ = await run_graph_internal(\\n        graph, flow_id, session_id=session_id, inputs=graph_run_inputs, outputs=[component_id]\\n    )\\n    return graph.get_vertex(component_id).built_object\\n\\n\\ndef build_component_instance_for_tests(version: str, module: str, file_name: str, **kwargs):\\n    component = download_component_from_github(module, file_name, version)\\n    cc_class = eval_custom_component_code(component._code)\\n    return cc_class(**kwargs), component._code\\n\\n\\ndef pyleak_marker(**extra_args):\\n    default_args = {\\n        \\\"enable_task_creation_tracking\\\": True,  # log task creation stacks\\n        \\\"thread_name_filter\\\": r\\\"^(?!asyncio_\\\\d+$).*\\\",  # exclude `asyncio_{num}` threads\\n        # Exclude the telemetry writer's background ticks (`telemetry-writer*`,\\n        # `telemetry-sweeper*`). They are long-lived daemons that legitimately\\n        # cycle wait_for wrappers across test boundaries; the writer's own\\n        # unit tests cover its lifecycle.\\n        \\\"task_name_filter\\\": r\\\"^(?!telemetry-).*\\\",\\n    }\\n    return pytest.mark.no_leaks(**default_args, **extra_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"86b8cb7c31de51716d83b53cdc0582cae0749c29747ba8833bcf750ce28bdd72\",\"content\":\"# Langflow Load Testing\\n\\nThis directory contains comprehensive load testing tools for both Langflow and LFX APIs using Locust.\\n\\n## \ud83d\udd27 **Two Testing Systems**\\n\\n### **Langflow API Testing** (Enhanced System)\\n\\n- Files: `langflow_*.py`\\n- Tests the main Langflow application API\\n- Includes automatic setup, real starter projects, and comprehensive error logging\\n\\n### **LFX API Testing** (Complex Serve)\\n\\n- Files: `lfx_*.py`\\n- Tests the LFX complex serve API\\n- Uses traditional load testing patterns\\n\\n## Features\\n\\n- **Automatic Environment Setup**: Creates users, API keys, and test flows automatically\\n- **Pre-flight Testing**: Validates connectivity and flow execution before load testing\\n- **Multiple User Types**: Different user behaviors to simulate realistic load patterns\\n- **Load Test Shapes**: Predefined load patterns for different testing scenarios\\n- **Comprehensive Metrics**: Performance grading and detailed reporting\\n- **Enhanced Error Logging**: Detailed connection error analysis and Langflow log capture\\n- **Easy Setup**: One-command execution with automatic Langflow startup\\n\\n## Quick Start\\n\\n### Prerequisites\\n\\n```bash\\n# Using uv (recommended)\\nuv add locust httpx\\n\\n# Or using pip\\npip install locust httpx\\n```\\n\\n### Using Makefile Commands (Recommended)\\n\\nThe easiest way to use the load testing system:\\n\\n```bash\\n# 1. Setup test environment (interactive flow selection)\\nmake load_test_setup\\n\\n# 2. Run a quick test\\nmake load_test_langflow_quick\\n\\n# 3. Run a full load test\\nmake load_test_run\\n\\n# 4. Clean up when done\\nmake load_test_clean\\n\\n# See all available commands\\nmake load_test_help\\n```\\n\\n## \ud83c\udf10 **Remote Instance Testing**\\n\\nFor testing against a remote Langflow instance:\\n\\n### Setup for Remote Testing\\n\\n```bash\\n# Using Makefile (recommended)\\nmake load_test_remote_setup LANGFLOW_HOST=\\\"https://your-remote-instance.com\\\"\\nmake load_test_remote_run LANGFLOW_HOST=\\\"https://your-remote-instance.com\\\"\\n\\n# Or using Python scripts directly\\npython langflow_setup_test.py --host https://your-remote-instance.com --interactive\\npython langflow_run_load_test.py --host https://your-remote-instance.com --no-start-langflow --headless --users 10 --duration 120\\n\\n# Test remote instance before setup (optional)\\npython diagnose_remote.py --host https://your-remote-instance.com --load-test 5\\n```\\n\\n### Important Notes for Remote Testing\\n\\n- **Always use `--no-start-langflow`** when testing remote instances\\n- **Use HTTPS** for production remote instances\\n- **Consider network latency** in your performance expectations\\n- **Monitor both client and server resources** during testing\\n- **Use realistic user counts** based on your remote instance specs\\n- **Start with fewer users** (10 instead of 20) to avoid overwhelming remote instances\\n- **Use slower spawn rates** (1 user/sec) for more realistic load patterns\\n- **Status code 0 errors** indicate connection failures, usually from overloading the remote instance\\n\\n### Two-Step Process\\n\\n#### Step 1: Setup (Run Once)\\n\\nChoose and set up a real Langflow starter project for testing:\\n\\n```bash\\n# Interactive flow selection\\npython langflow_setup_test.py --interactive\\n\\n# Use specific flow\\npython langflow_setup_test.py --flow \\\"Memory Chatbot\\\"\\n\\n# List available flows\\npython langflow_setup_test.py --list-flows\\n```\\n\\nThis will:\\n\\n- Use `LANGFLOW_SUPERUSER` / `LANGFLOW_SUPERUSER_PASSWORD` or AUTO_LOGIN\\n- Generate API keys\\n- Upload a real starter project flow\\n- Provide credentials for load testing\\n\\n#### Step 2: Run Load Tests\\n\\n```bash\\n# Interactive mode with web UI\\npython langflow_run_load_test.py\\n\\n# Headless mode with 20 users for 2 minutes\\npython langflow_run_load_test.py --headless --users 20 --duration 120\\n\\n# Use predefined load shape\\npython langflow_run_load_test.py --shape ramp100 --headless --users 100 --duration 180\\n```\\n\\n### Advanced Usage\\n\\n```bash\\n# Setup with custom host (e.g., remote instance)\\npython langflow_setup_test.py --host https://your-remote-instance.com --interactive\\n\\n# Save credentials to file\\npython langflow_setup_test.py --interactive --save-credentials my_test_creds.json\\n\\n# Test against existing remote Langflow instance\\npython langflow_run_load_test.py --host https://your-remote-instance.com --no-start-langflow\\n\\n# Save results to CSV and HTML\\npython langflow_run_load_test.py --headless --csv results --html report.html --users 50 --duration 300\\n\\n# Direct Locust usage (after setup)\\nexport API_KEY=\\\"your-api-key-from-setup\\\"\\nexport FLOW_ID=\\\"your-flow-id-from-setup\\\"\\nlocust -f langflow_locustfile.py --host http://localhost:7860\\n\\n# Distributed testing (master)\\nlocust -f langflow_locustfile.py --host http://localhost:7860 --master\\n\\n# Distributed testing (worker)\\nlocust -f langflow_locustfile.py --host http://localhost:7860 --worker --master-host=localhost\\n```\\n\\n## User Types\\n\\nThe load test includes multiple user types that simulate different usage patterns:\\n\\n- **NormalUser** (default): Typical user behavior with realistic message distribution\\n- **AggressiveUser**: High-frequency requests with minimal wait times\\n- **SustainedLoadUser**: Constant 1 RPS per user for steady load testing\\n- **TailLatencyHunter**: Mixed workload to expose tail latency issues\\n- **ScalabilityTestUser**: Tests for scaling limits and performance cliffs\\n- **BurstUser**: Sends bursts of requests to test connection pooling\\n\\n## Load Test Shapes\\n\\nPredefined load patterns for different testing scenarios:\\n\\n- **RampToHundred**: 0 \u2192 100 users over 20 seconds, hold for 3 minutes\\n- **StepRamp**: Step increases every 30 seconds to find performance cliffs\\n\\nUse with: `--shape ramp100` or `--shape stepramp`\\n\\n## Environment Variables\\n\\n- `LANGFLOW_HOST`: Base URL for Langflow server (default: http://localhost:7860)\\n- `SHAPE`: Load test shape (ramp100, stepramp)\\n- `REQUEST_TIMEOUT`: Request timeout in seconds (default: 30.0)\\n\\n## Architecture\\n\\n### Setup Process (`langflow_setup_test.py`)\\n\\n1. **Health Check**: Verify Langflow is running\\n2. **Flow Selection**: Choose from 40+ real starter project flows\\n3. **Authentication**: Login with configured credentials or AUTO_LOGIN\\n4. **API Key Generation**: Create API key for load testing\\n5. **Flow Upload**: Upload the selected starter project flow\\n6. **Credential Export**: Provide environment variables for testing\\n\\n### Real Starter Project Flows\\n\\nInstead of simple test flows, the system uses real Langflow starter projects:\\n\\n- **Basic Prompting**: Simple LLM interaction\\n- **Memory Chatbot**: Conversational AI with memory\\n- **Document Q&A**: RAG-based document questioning\\n- **Research Agent**: Multi-step research workflows\\n- **Vector Store RAG**: Advanced retrieval-augmented generation\\n- **And 35+ more realistic flows**\\n\\nThis provides much more realistic load testing scenarios that exercise:\\n\\n- Complex node graphs and dependencies\\n- Real LLM integrations\\n- Vector databases and embeddings\\n- Multi-step agent workflows\\n- Memory and state management\\n\\n## Performance Grading\\n\\nThe load test provides automatic performance grading:\\n\\n- **Grade A**: Excellent performance, production ready\\n- **Grade B**: Good performance with minor issues\\n- **Grade C**: Acceptable but monitor closely\\n- **Grade D**: Performance issues detected\\n- **Grade F**: Significant problems, not production ready\\n\\nGrading is based on:\\n\\n- Failure rate (< 1% for A grade)\\n- 95th percentile response time (< 10s for good grades)\\n- Request throughput and consistency\\n\\n## Monitoring\\n\\nThe test tracks:\\n\\n- Response times (p50, p95, p99)\\n- Request rates and throughput\\n- Failure rates and error types\\n- Slow requests (>10s, >20s)\\n- Connection and timeout issues\\n\\n## Troubleshooting\\n\\n### Common Issues\\n\\n1. **Setup Failed**: Ensure Langflow is accessible and not in read-only mode\\n2. **Authentication Errors**: Set `LANGFLOW_SUPERUSER` and `LANGFLOW_SUPERUSER_PASSWORD`, or enable `LANGFLOW_AUTO_LOGIN`\\n3. **Flow Creation Failed**: Verify the user has permission to create flows\\n4. **Connection Errors**: Check network connectivity and firewall settings\\n5. **Status Code 0 Errors**: Usually indicates connection overload - reduce user count or spawn rate\\n\\n### Debug Mode\\n\\nFor debugging, you can:\\n\\n1. Run Langflow manually with `--log-level debug`\\n2. Check the Langflow logs for detailed error information\\n3. Use the web UI to verify the test flow was created correctly\\n4. Test API endpoints manually with curl or httpx\\n5. Use the diagnostic tool for remote instances: `python diagnose_remote.py --host <url> --load-test 10`\\n\\n### Manual Setup\\n\\nIf automatic setup fails, you can set up manually:\\n\\n1. Start Langflow: `python -m langflow run --auto-login`\\n2. Create a user account through the UI\\n3. Create an API key in the settings\\n4. Create a simple flow and note its ID\\n5. Set environment variables and run Locust directly\\n\\n```bash\\nexport API_KEY=\\\"your-api-key\\\"\\nexport FLOW_ID=\\\"your-flow-id\\\"\\nlocust -f langflow_locustfile.py --host http://localhost:7860\\n```\\n\\n## Contributing\\n\\nWhen adding new user types or test scenarios:\\n\\n1. Inherit from `BaseLangflowUser`\\n2. Implement task methods with `@task` decorator\\n3. Use `self.make_request()` for consistent error handling\\n4. Add appropriate weight and wait_time settings\\n5. Document the user type's purpose and behavior\\n\\n## Examples\\n\\n### Basic Load Test\\n\\n```bash\\npython langflow_run_load_test.py --headless --users 10 --duration 60\\n```\\n\\n### Stress Test\\n\\n```bash\\npython langflow_run_load_test.py --shape ramp100 --headless --users 100 --duration 300\\n```\\n\\n### Performance Profiling\\n\\n```bash\\npython langflow_run_load_test.py --shape stepramp --headless --csv profile_results\\n```\\n\\n### Production Readiness Test\\n\\n```bash\\npython langflow_run_load_test.py --users 50 --duration 600 --csv production_test --html production_report.html\\n```\\n\\n## \ud83d\udcca HTML Reports\\n\\nThe system generates beautiful HTML reports with:\\n\\n- **Interactive Charts**: Response time graphs, throughput charts\\n- **Detailed Statistics**: Request/response metrics, percentiles\\n- **Error Analysis**: Failure breakdown and error patterns\\n- **Performance Timeline**: Real-time performance during the test\\n- **User Behavior Analysis**: Breakdown by user type and task\\n\\n### HTML Report Examples\\n\\n```bash\\n# Generate comprehensive HTML report\\npython langflow_run_load_test.py --headless --users 25 --duration 120 --html detailed_report.html\\n\\n# Combined CSV + HTML reporting\\npython langflow_run_load_test.py --headless --users 100 --duration 300 --csv data --html analysis.html --shape ramp100\\n\\n# Quick test with report\\npython langflow_setup_test.py --flow \\\"Memory Chatbot\\\"\\npython langflow_run_load_test.py --headless --users 10 --duration 60 --html quick_test.html\\n```\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/diagnose_remote.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5e85505128844e2fa213fa07b31353538c1fa13171ccfc8472961e8db8e26c68\",\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Diagnostic tool for remote Langflow instances.\\n\\nHelps debug connection issues and performance problems.\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport json\\nimport sys\\nimport time\\nfrom typing import Any\\n\\nimport httpx\\n\\n\\ndef test_connectivity(host: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Test basic connectivity to the host.\\\"\\\"\\\"\\n    print(f\\\"\ud83d\udd17 Testing connectivity to {host}\\\")\\n\\n    results = {\\n        \\\"host\\\": host,\\n        \\\"reachable\\\": False,\\n        \\\"health_check\\\": False,\\n        \\\"response_time_ms\\\": None,\\n        \\\"error\\\": None,\\n    }\\n\\n    try:\\n        start_time = time.time()\\n        with httpx.Client(timeout=30.0) as client:\\n            response = client.get(f\\\"{host}/health\\\")\\n            end_time = time.time()\\n\\n            results[\\\"reachable\\\"] = True\\n            results[\\\"response_time_ms\\\"] = round((end_time - start_time) * 1000, 2)\\n            results[\\\"health_check\\\"] = response.status_code == 200\\n            results[\\\"status_code\\\"] = response.status_code\\n\\n            if response.status_code == 200:\\n                print(f\\\"   \u2705 Health check passed ({results['response_time_ms']}ms)\\\")\\n            else:\\n                print(f\\\"   \u26a0\ufe0f  Health check failed: {response.status_code}\\\")\\n                results[\\\"error\\\"] = f\\\"HTTP {response.status_code}\\\"\\n\\n    except Exception as e:\\n        results[\\\"error\\\"] = f\\\"{type(e).__name__}: {e}\\\"\\n        print(f\\\"   \u274c Connection failed: {results['error']}\\\")\\n\\n    return results\\n\\n\\ndef test_flow_endpoint(host: str, api_key: str, flow_id: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Test a flow execution request.\\\"\\\"\\\"\\n    print(\\\"\ud83c\udfaf Testing flow execution\\\")\\n\\n    results = {\\n        \\\"success\\\": False,\\n        \\\"response_time_ms\\\": None,\\n        \\\"status_code\\\": None,\\n        \\\"error\\\": None,\\n        \\\"has_outputs\\\": False,\\n    }\\n\\n    try:\\n        url = f\\\"{host}/api/v1/run/{flow_id}?stream=false\\\"\\n        payload = {\\n            \\\"input_value\\\": \\\"Hello, this is a diagnostic test\\\",\\n            \\\"output_type\\\": \\\"chat\\\",\\n            \\\"input_type\\\": \\\"chat\\\",\\n            \\\"tweaks\\\": {},\\n        }\\n        headers = {\\\"x-api-key\\\": api_key, \\\"Content-Type\\\": \\\"application/json\\\"}\\n\\n        start_time = time.time()\\n        with httpx.Client(timeout=60.0) as client:\\n            response = client.post(url, json=payload, headers=headers)\\n            end_time = time.time()\\n\\n        results[\\\"response_time_ms\\\"] = round((end_time - start_time) * 1000, 2)\\n        results[\\\"status_code\\\"] = response.status_code\\n\\n        if response.status_code == 200:\\n            try:\\n                data = response.json()\\n                results[\\\"has_outputs\\\"] = bool(data.get(\\\"outputs\\\"))\\n                results[\\\"success\\\"] = results[\\\"has_outputs\\\"]\\n\\n                if results[\\\"success\\\"]:\\n                    print(f\\\"   \u2705 Flow execution successful ({results['response_time_ms']}ms)\\\")\\n                else:\\n                    print(f\\\"   \u26a0\ufe0f  Flow executed but no outputs ({results['response_time_ms']}ms)\\\")\\n                    results[\\\"error\\\"] = \\\"No outputs in response\\\"\\n\\n            except Exception as e:\\n                results[\\\"error\\\"] = f\\\"JSON decode error: {e}\\\"\\n                print(f\\\"   \u274c Invalid JSON response: {e}\\\")\\n        else:\\n            results[\\\"error\\\"] = f\\\"HTTP {response.status_code}\\\"\\n            print(f\\\"   \u274c Flow execution failed: {response.status_code}\\\")\\n            print(f\\\"      Response: {response.text[:200]}...\\\")\\n\\n    except Exception as e:\\n        results[\\\"error\\\"] = f\\\"{type(e).__name__}: {e}\\\"\\n        print(f\\\"   \u274c Request failed: {results['error']}\\\")\\n\\n    return results\\n\\n\\ndef run_load_simulation(host: str, api_key: str, flow_id: str, num_requests: int = 10) -> dict[str, Any]:\\n    \\\"\\\"\\\"Run a small load simulation to test performance.\\\"\\\"\\\"\\n    print(f\\\"\u26a1 Running mini load test ({num_requests} requests)\\\")\\n\\n    results = {\\n        \\\"total_requests\\\": num_requests,\\n        \\\"successful_requests\\\": 0,\\n        \\\"failed_requests\\\": 0,\\n        \\\"connection_errors\\\": 0,\\n        \\\"response_times\\\": [],\\n        \\\"errors\\\": [],\\n    }\\n\\n    url = f\\\"{host}/api/v1/run/{flow_id}?stream=false\\\"\\n    payload = {\\n        \\\"input_value\\\": \\\"Load test message\\\",\\n        \\\"output_type\\\": \\\"chat\\\",\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"tweaks\\\": {},\\n    }\\n    headers = {\\\"x-api-key\\\": api_key, \\\"Content-Type\\\": \\\"application/json\\\"}\\n\\n    for i in range(num_requests):\\n        try:\\n            start_time = time.time()\\n            with httpx.Client(timeout=30.0) as client:\\n                response = client.post(url, json=payload, headers=headers)\\n                end_time = time.time()\\n\\n            response_time = round((end_time - start_time) * 1000, 2)\\n            results[\\\"response_times\\\"].append(response_time)\\n\\n            if response.status_code == 200:\\n                try:\\n                    data = response.json()\\n                    if data.get(\\\"outputs\\\"):\\n                        results[\\\"successful_requests\\\"] += 1\\n                        print(f\\\"   \u2705 Request {i + 1}: {response_time}ms\\\")\\n                    else:\\n                        results[\\\"failed_requests\\\"] += 1\\n                        results[\\\"errors\\\"].append(f\\\"Request {i + 1}: No outputs\\\")\\n                        print(f\\\"   \u26a0\ufe0f  Request {i + 1}: No outputs ({response_time}ms)\\\")\\n                except Exception as e:\\n                    results[\\\"failed_requests\\\"] += 1\\n                    results[\\\"errors\\\"].append(f\\\"Request {i + 1}: JSON error - {e}\\\")\\n                    print(f\\\"   \u274c Request {i + 1}: JSON error ({response_time}ms)\\\")\\n            else:\\n                results[\\\"failed_requests\\\"] += 1\\n                results[\\\"errors\\\"].append(f\\\"Request {i + 1}: HTTP {response.status_code}\\\")\\n                print(f\\\"   \u274c Request {i + 1}: HTTP {response.status_code} ({response_time}ms)\\\")\\n\\n        except Exception as e:\\n            results[\\\"connection_errors\\\"] += 1\\n            results[\\\"errors\\\"].append(f\\\"Request {i + 1}: {type(e).__name__} - {e}\\\")\\n            print(f\\\"   \ud83d\udca5 Request {i + 1}: Connection error - {e}\\\")\\n\\n    # Calculate statistics\\n    if results[\\\"response_times\\\"]:\\n        results[\\\"avg_response_time\\\"] = round(sum(results[\\\"response_times\\\"]) / len(results[\\\"response_times\\\"]), 2)\\n        results[\\\"min_response_time\\\"] = min(results[\\\"response_times\\\"])\\n        results[\\\"max_response_time\\\"] = max(results[\\\"response_times\\\"])\\n\\n    return results\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=\\\"Diagnose remote Langflow instance\\\")\\n    parser.add_argument(\\\"--host\\\", required=True, help=\\\"Langflow host URL\\\")\\n    parser.add_argument(\\\"--api-key\\\", help=\\\"API key for flow execution\\\")\\n    parser.add_argument(\\\"--flow-id\\\", help=\\\"Flow ID for testing\\\")\\n    parser.add_argument(\\\"--load-test\\\", type=int, default=0, help=\\\"Number of requests for mini load test\\\")\\n    parser.add_argument(\\\"--output\\\", help=\\\"Save results to JSON file\\\")\\n\\n    args = parser.parse_args()\\n\\n    print(f\\\"\ud83d\udd0d Diagnosing Langflow instance: {args.host}\\\")\\n    print(\\\"=\\\" * 60)\\n\\n    # Test basic connectivity\\n    connectivity_results = test_connectivity(args.host)\\n\\n    # Test flow execution if credentials provided\\n    flow_results = None\\n    if args.api_key and args.flow_id:\\n        flow_results = test_flow_endpoint(args.host, args.api_key, args.flow_id)\\n    else:\\n        print(\\\"\u26a0\ufe0f  Skipping flow test (no API key or flow ID provided)\\\")\\n\\n    # Run mini load test if requested\\n    load_results = None\\n    if args.load_test > 0 and args.api_key and args.flow_id:\\n        load_results = run_load_simulation(args.host, args.api_key, args.flow_id, args.load_test)\\n\\n    # Summary\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 60)\\n    print(\\\"\ud83d\udccb DIAGNOSTIC SUMMARY\\\")\\n    print(\\\"=\\\" * 60)\\n\\n    print(f\\\"Host: {args.host}\\\")\\n    print(f\\\"Connectivity: {'\u2705 OK' if connectivity_results['reachable'] else '\u274c FAILED'}\\\")\\n    print(f\\\"Health Check: {'\u2705 OK' if connectivity_results['health_check'] else '\u274c FAILED'}\\\")\\n\\n    if connectivity_results[\\\"response_time_ms\\\"]:\\n        print(f\\\"Health Response Time: {connectivity_results['response_time_ms']}ms\\\")\\n\\n    if flow_results:\\n        print(f\\\"Flow Execution: {'\u2705 OK' if flow_results['success'] else '\u274c FAILED'}\\\")\\n        if flow_results[\\\"response_time_ms\\\"]:\\n            print(f\\\"Flow Response Time: {flow_results['response_time_ms']}ms\\\")\\n\\n    if load_results:\\n        success_rate = (load_results[\\\"successful_requests\\\"] / load_results[\\\"total_requests\\\"]) * 100\\n        print(\\n            f\\\"Mini Load Test: {load_results['successful_requests']}/{load_results['total_requests']} ({success_rate:.1f}% success)\\\"\\n        )\\n        if load_results.get(\\\"avg_response_time\\\"):\\n            print(f\\\"Average Response Time: {load_results['avg_response_time']}ms\\\")\\n\\n    # Recommendations\\n    print(\\\"\\\\n\ud83d\udd27 RECOMMENDATIONS:\\\")\\n    if not connectivity_results[\\\"reachable\\\"]:\\n        print(\\\"\u274c Cannot reach the host - check URL and network connectivity\\\")\\n    elif not connectivity_results[\\\"health_check\\\"]:\\n        print(\\\"\u274c Health check failed - Langflow may not be running properly\\\")\\n    elif flow_results and not flow_results[\\\"success\\\"]:\\n        print(\\\"\u274c Flow execution failed - check API key, flow ID, and flow configuration\\\")\\n    elif load_results and load_results[\\\"connection_errors\\\"] > 0:\\n        print(\\\"\u26a0\ufe0f  Connection errors detected - instance may be overloaded or unstable\\\")\\n    elif load_results and load_results.get(\\\"avg_response_time\\\", 0) > 10000:\\n        print(\\\"\u26a0\ufe0f  Slow response times - consider reducing load or optimizing flow\\\")\\n    else:\\n        print(\\\"\u2705 Instance appears healthy for load testing\\\")\\n\\n    # Save results if requested\\n    if args.output:\\n        results = {\\n            \\\"timestamp\\\": time.time(),\\n            \\\"host\\\": args.host,\\n            \\\"connectivity\\\": connectivity_results,\\n            \\\"flow_execution\\\": flow_results,\\n            \\\"load_simulation\\\": load_results,\\n        }\\n\\n        with open(args.output, \\\"w\\\") as f:\\n            json.dump(results, f, indent=2)\\n        print(f\\\"\\\\n\ud83d\udcbe Results saved to: {args.output}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/lfx_serve_locustfile.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0fc097cea1624ef6aead93f891401e01242726daddf96d58e4a39eadc5ced5f\",\"content\":\"\\\"\\\"\\\"LFX Locust Load Testing File.\\n\\nBased on the weakness-focused stress test scripts with additional user behaviors.\\nIncludes production-ready fixes for timing, error handling, and reporting.\\n\\nThis file tests the LFX API (complex serve), not the Langflow API.\\n\\nUsage:\\n    # Run with web UI (recommended)\\n    locust -f locustfile_complex_serve.py --host http://127.0.0.1:8000\\n\\n    # Run headless with built-in shape\\n    locust -f locustfile_complex_serve.py --host http://127.0.0.1:8000 --headless --shape RampToHundred\\n\\n    # Run distributed (master)\\n    locust -f locustfile_complex_serve.py --host http://127.0.0.1:8000 --master\\n\\n    # Run distributed (worker)\\n    locust -f locustfile_complex_serve.py --host http://127.0.0.1:8000 --worker --master-host=localhost\\n\\nEnvironment Variables:\\n    - FLOW_ID: Flow ID to test (default: 5523731d-5ef3-56de-b4ef-59b0a224fdbc)\\n    - API_KEY: API key for authentication (default: test)\\n    - REQUEST_TIMEOUT: Request timeout in seconds (default: 10)\\n    - SHAPE: Load test shape to use (default: none, options: ramp100)\\n\\\"\\\"\\\"\\n\\nimport inspect\\nimport json\\nimport os\\nimport random\\nimport time\\n\\nimport gevent\\nfrom locust import FastHttpUser, LoadTestShape, between, constant, constant_pacing, events, task\\n\\n# Configuration\\nFLOW_ID = os.getenv(\\\"FLOW_ID\\\", \\\"5523731d-5ef3-56de-b4ef-59b0a224fdbc\\\")\\nAPI_KEY = os.getenv(\\\"API_KEY\\\", \\\"test\\\")\\nAPI_ENDPOINT = f\\\"/flows/{FLOW_ID}/run\\\"\\n\\n# Test messages with realistic distribution\\nTEST_MESSAGES = {\\n    \\\"minimal\\\": \\\"Hi\\\",\\n    \\\"simple\\\": \\\"Can you help me?\\\",\\n    \\\"medium\\\": \\\"I need help understanding how machine learning works in this context.\\\",\\n    \\\"complex\\\": \\\"Please analyze this data: \\\" + \\\"x\\\" * 500 + \\\" and provide detailed insights.\\\",\\n    \\\"large\\\": \\\"Here's a complex scenario: \\\" + \\\"data \\\" * 1000,\\n}\\n\\n# Weighted message distribution for realistic load\\nMESSAGE_WEIGHTS = [(\\\"simple\\\", 50), (\\\"medium\\\", 30), (\\\"minimal\\\", 15), (\\\"complex\\\", 4), (\\\"large\\\", 1)]\\n\\n\\n# Load test shapes\\nclass RampToHundred(LoadTestShape):\\n    \\\"\\\"\\\"0 -> 100 users at 5 users/sec (20s ramp), then hold until 180s total.\\n\\n    Matches the TLDR test pattern: 3 minutes, ramping to 100 users.\\n    \\\"\\\"\\\"\\n\\n    spawn_rate = 5\\n    target_users = 100\\n    total_duration = 180  # seconds\\n\\n    def tick(self):\\n        run_time = self.get_run_time()\\n        if run_time >= self.total_duration:\\n            return None\\n        users = min(int(run_time * self.spawn_rate), self.target_users)\\n        return users, self.spawn_rate\\n\\n\\nclass StepRamp(LoadTestShape):\\n    \\\"\\\"\\\"Step ramp for finding performance cliffs.\\n\\n    Steps every 30 seconds: 5 -> 10 -> 15 -> 20 -> 25 -> 30 -> 35 users.\\n    Each step holds for exactly 30 seconds to measure steady-state performance.\\n    \\\"\\\"\\\"\\n\\n    def tick(self):\\n        run_time = self.get_run_time()\\n\\n        # Define the step progression with 30-second intervals\\n        steps = [\\n            (30, 5),  # 0-30s: 5 users\\n            (60, 10),  # 30-60s: 10 users\\n            (90, 15),  # 60-90s: 15 users\\n            (120, 20),  # 90-120s: 20 users\\n            (150, 25),  # 120-150s: 25 users\\n            (180, 30),  # 150-180s: 30 users\\n            (210, 35),  # 180-210s: 35 users\\n            (240, 40),  # 210-240s: 40 users\\n            (270, 45),  # 240-270s: 45 users\\n            (300, 50),  # 270-300s: 50 users\\n        ]\\n\\n        # Find current step\\n        for time_limit, user_count in steps:\\n            if run_time < time_limit:\\n                return user_count, 10  # Fast spawn rate for quick transitions\\n\\n        return None  # End test after 300 seconds\\n\\n\\n# Environment-scoped metrics tracking (fixes the event listener issue)\\n_env_bags = {}\\n\\n\\n@events.test_start.add_listener\\ndef on_test_start(environment, **_kwargs):\\n    \\\"\\\"\\\"Initialize per-environment metrics tracking.\\\"\\\"\\\"\\n    _env_bags[environment] = {\\n        \\\"slow_10s\\\": 0,\\n        \\\"slow_20s\\\": 0,\\n    }\\n\\n\\n@events.request.add_listener\\ndef on_request(request_type, name, response_time, response_length, exception, context, **kwargs):  # noqa: ARG001\\n    \\\"\\\"\\\"Track slow requests using Locust's built-in timing.\\\"\\\"\\\"\\n    # response_time is in milliseconds from Locust\\n    bag = _env_bags.get(context.get(\\\"environment\\\") if context else None)\\n    if bag is None:\\n        # fallback: try the single environment we likely have\\n        if len(_env_bags) == 1:\\n            bag = next(iter(_env_bags.values()))\\n        else:\\n            return\\n\\n    if exception is None:  # Only count successful requests for timing\\n        if response_time > 10_000:  # 10 seconds in ms\\n            bag[\\\"slow_10s\\\"] += 1\\n        if response_time > 20_000:  # 20 seconds in ms\\n            bag[\\\"slow_20s\\\"] += 1\\n\\n\\n@events.test_stop.add_listener\\ndef on_test_stop(environment, **_kwargs):\\n    \\\"\\\"\\\"Print comprehensive test summary with performance grading.\\\"\\\"\\\"\\n    stats = environment.stats.total\\n    if stats.num_requests == 0:\\n        return\\n\\n    # Get percentiles and basic stats\\n    stats.get_response_time_percentile(0.50) or 0\\n    p95 = stats.get_response_time_percentile(0.95) or 0\\n    stats.get_response_time_percentile(0.99) or 0\\n    fail_ratio = stats.fail_ratio\\n    getattr(stats, \\\"current_rps\\\", 0.0)\\n\\n    # Get slow request counts\\n    _env_bags.get(environment, {\\\"slow_10s\\\": 0, \\\"slow_20s\\\": 0})\\n\\n    # Performance grading based on production criteria\\n    grade = \\\"A\\\"\\n    issues = []\\n\\n    if fail_ratio > 0.01:\\n        grade = \\\"B\\\"\\n        issues.append(f\\\"fail {fail_ratio:.1%}\\\")\\n    if fail_ratio > 0.05:\\n        grade = \\\"C\\\"\\n    if p95 > 10_000:\\n        grade = max(grade, \\\"D\\\")\\n        issues.append(f\\\"p95 {p95 / 1000:.1f}s\\\")\\n    if p95 > 20_000:\\n        grade = \\\"F\\\"\\n        issues.append(f\\\"p95 {p95 / 1000:.1f}s\\\")\\n\\n    # Production readiness assessment\\n    if grade in [\\\"A\\\", \\\"B\\\"] or grade == \\\"C\\\":\\n        pass\\n    else:\\n        pass\\n\\n    # Cleanup\\n    _env_bags.pop(environment, None)\\n\\n\\nclass BaseLfxUser(FastHttpUser):\\n    \\\"\\\"\\\"Base class for all LFX API load testing user types.\\\"\\\"\\\"\\n\\n    abstract = True\\n    REQUEST_TIMEOUT = float(os.getenv(\\\"REQUEST_TIMEOUT\\\", \\\"10\\\"))  # Tighter timeout for production\\n\\n    def on_start(self):\\n        \\\"\\\"\\\"Called when a user starts before any task is scheduled.\\\"\\\"\\\"\\n        self.session_id = f\\\"locust_{self.__class__.__name__}_{id(self)}_{int(time.time())}\\\"\\n        self.request_count = 0\\n\\n    def make_request(self, message_type=\\\"simple\\\", tag_suffix=\\\"\\\"):\\n        \\\"\\\"\\\"Make a request with proper error handling and timing.\\n\\n        Uses Locust's built-in response time measurement.\\n        \\\"\\\"\\\"\\n        message = TEST_MESSAGES.get(message_type, TEST_MESSAGES[\\\"simple\\\"])\\n\\n        payload = {\\\"input_value\\\": message, \\\"session_id\\\": f\\\"{self.session_id}_{self.request_count}\\\"}\\n\\n        headers = {\\\"x-api-key\\\": API_KEY, \\\"Content-Type\\\": \\\"application/json\\\"}\\n\\n        self.request_count += 1\\n        name = f\\\"{API_ENDPOINT} [{message_type}{tag_suffix}]\\\"\\n\\n        with self.client.post(\\n            API_ENDPOINT,\\n            json=payload,\\n            headers=headers,\\n            name=name,\\n            timeout=self.REQUEST_TIMEOUT,\\n            catch_response=True,\\n        ) as response:\\n            # Handle successful responses\\n            if response.status_code == 200:\\n                try:\\n                    data = response.json()\\n                except json.JSONDecodeError:\\n                    return response.failure(\\\"Invalid JSON response\\\")\\n\\n                # Strictly check for success=True in the response payload\\n                success = data.get(\\\"success\\\")\\n                if success is True:\\n                    return response.success()\\n\\n                # Application-level failure - success is False, None, or missing\\n                msg = str(data.get(\\\"result\\\", \\\"Unknown error\\\"))[:200]\\n                success_status = f\\\"success={success}\\\" if success is not None else \\\"success=missing\\\"\\n                return response.failure(f\\\"Flow failed ({success_status}): {msg}\\\")\\n\\n            # Handle specific error cases for better monitoring\\n            if response.status_code in (429, 503):\\n                return response.failure(f\\\"Backpressure/capacity: {response.status_code}\\\")\\n            if response.status_code == 401:\\n                return response.failure(\\\"Unauthorized - API key issue\\\")\\n            if response.status_code == 404:\\n                return response.failure(\\\"Flow not found - check FLOW_ID\\\")\\n            if response.status_code >= 500:\\n                return response.failure(f\\\"Server error {response.status_code}\\\")\\n\\n            return response.failure(f\\\"HTTP {response.status_code}\\\")\\n\\n\\nclass NormalUser(BaseLfxUser):\\n    \\\"\\\"\\\"Normal user simulating typical API interactions.\\n\\n    Based on the main stress test patterns with realistic message distribution.\\n    \\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(0.5, 2)  # Typical user think time\\n\\n    @task(80)\\n    def send_message(self):\\n        \\\"\\\"\\\"Main task: Send a message with weighted distribution.\\\"\\\"\\\"\\n        message_type = random.choices([w[0] for w in MESSAGE_WEIGHTS], weights=[w[1] for w in MESSAGE_WEIGHTS], k=1)[0]  # noqa: S311\\n        self.make_request(message_type=message_type)\\n\\n    @task(15)\\n    def send_burst(self):\\n        \\\"\\\"\\\"Send a burst of 3 small messages quickly.\\\"\\\"\\\"\\n        for i in range(3):\\n            self.make_request(message_type=\\\"minimal\\\", tag_suffix=f\\\"-burst{i}\\\")\\n            gevent.sleep(0.1)  # Small delay between burst requests\\n\\n    @task(5)\\n    def send_complex(self):\\n        \\\"\\\"\\\"Occasionally send complex requests that stress the system.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"complex\\\")\\n\\n\\nclass AggressiveUser(BaseLfxUser):\\n    \\\"\\\"\\\"Aggressive user with minimal wait times.\\n\\n    Tests the system under extreme concurrent load.\\n    \\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(0.1, 0.3)  # Very aggressive\\n\\n    @task\\n    def rapid_fire(self):\\n        \\\"\\\"\\\"Send requests as fast as possible.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"simple\\\", tag_suffix=\\\"-rapid\\\")\\n\\n\\nclass SustainedLoadUser(BaseLfxUser):\\n    \\\"\\\"\\\"Maintains exactly 1 request/second for steady load testing.\\n\\n    Based on constant throughput testing patterns.\\n    \\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = constant_pacing(1)  # Exactly 1 request per second per user\\n\\n    @task\\n    def steady_load(self):\\n        \\\"\\\"\\\"Send requests at constant 1 RPS per user.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"medium\\\", tag_suffix=\\\"-steady\\\")\\n\\n\\nclass TailLatencyHunter(BaseLfxUser):\\n    \\\"\\\"\\\"Mixed workload designed to expose tail latency issues.\\n\\n    Alternates between light and heavy requests to stress the system.\\n    \\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(0.8, 1.5)\\n\\n    @task\\n    def hunt_tail_latency(self):\\n        \\\"\\\"\\\"Alternate between simple and complex requests to find tail latency.\\\"\\\"\\\"\\n        if random.random() < 0.7:  # noqa: S311\\n            self.make_request(message_type=\\\"simple\\\", tag_suffix=\\\"-tail\\\")\\n        else:\\n            self.make_request(message_type=\\\"large\\\", tag_suffix=\\\"-tail-heavy\\\")\\n\\n\\nclass ScalabilityTestUser(BaseLfxUser):\\n    \\\"\\\"\\\"Tests for the scalability cliff at 30 users.\\n\\n    Uses patterns that specifically stress concurrency limits.\\n    \\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = constant(1.0)  # Constant load to test scaling\\n\\n    @task\\n    def scalability_test(self):\\n        \\\"\\\"\\\"Send medium complexity requests to test scaling limits.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"medium\\\", tag_suffix=\\\"-scale\\\")\\n\\n\\nclass BurstUser(BaseLfxUser):\\n    \\\"\\\"\\\"Sends bursts of 10 requests to test connection pooling.\\n\\n    Based on connection pool exhaustion test patterns.\\n    \\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(5, 10)  # Long wait between bursts\\n\\n    @task\\n    def burst_attack(self):\\n        \\\"\\\"\\\"Send a burst of 10 requests quickly to test connection handling.\\\"\\\"\\\"\\n        for i in range(10):\\n            self.make_request(message_type=\\\"minimal\\\", tag_suffix=f\\\"-burst{i}\\\")\\n            gevent.sleep(0.05)  # 50ms between requests in burst\\n\\n\\n# Auto-select shape based on environment variable\\n\\n_shape_env = os.getenv(\\\"SHAPE\\\", \\\"\\\").lower()\\n_selected = None\\n\\nif _shape_env == \\\"stepramp\\\":\\n    _selected = StepRamp\\nelif _shape_env == \\\"ramp100\\\":\\n    _selected = RampToHundred\\n\\nif _selected:\\n    # Create a single exported shape class and remove others so Locust sees only one\\n    class SelectedLoadTestShape(_selected):\\n        pass\\n\\n    # Remove other shape classes so Locust auto-picks the selected one\\n    for _name, _obj in list(globals().items()):\\n        if (\\n            inspect.isclass(_obj)\\n            and issubclass(_obj, LoadTestShape)\\n            and _obj is not SelectedLoadTestShape\\n            and _obj is not LoadTestShape\\n        ):\\n            del globals()[_name]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/lfx_step_ramp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0e69740f23bce0b8b43d954591927c5c3d9207569d4ac0de7cec848ae939f3cb\",\"content\":\"\\\"\\\"\\\"LFX Step Ramp Load Test for Finding Performance Cliffs.\\n\\nThis file tests the LFX API (complex serve), not the Langflow API.\\n\\nSteps every 30 seconds: 5 -> 10 -> 15 -> 20 -> 25 -> 30 -> 35 users.\\nEach step holds for exactly 30 seconds to measure steady-state performance.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport time\\n\\nfrom locust import FastHttpUser, LoadTestShape, between, events, task\\n\\n# Configuration\\nFLOW_ID = os.getenv(\\\"FLOW_ID\\\", \\\"5523731d-5ef3-56de-b4ef-59b0a224fdbc\\\")\\nAPI_KEY = os.getenv(\\\"API_KEY\\\", \\\"test\\\")\\nAPI_ENDPOINT = f\\\"/flows/{FLOW_ID}/run\\\"\\n\\n# Test messages\\nTEST_MESSAGES = {\\n    \\\"minimal\\\": \\\"Hi\\\",\\n    \\\"simple\\\": \\\"Can you help me?\\\",\\n    \\\"medium\\\": \\\"I need help understanding how machine learning works in this context.\\\",\\n    \\\"complex\\\": \\\"Please analyze this data: \\\" + \\\"x\\\" * 500 + \\\" and provide detailed insights.\\\",\\n    \\\"large\\\": \\\"Here's a complex scenario: \\\" + \\\"data \\\" * 1000,\\n}\\n\\nMESSAGE_WEIGHTS = [(\\\"simple\\\", 50), (\\\"medium\\\", 30), (\\\"minimal\\\", 15), (\\\"complex\\\", 4), (\\\"large\\\", 1)]\\n\\n\\nclass StepRamp(LoadTestShape):\\n    \\\"\\\"\\\"Step ramp for finding performance cliffs.\\\"\\\"\\\"\\n\\n    def tick(self):\\n        run_time = self.get_run_time()\\n\\n        # Step every 30 seconds\\n        steps = [\\n            (30, 5),  # 0-30s: 5 users\\n            (60, 10),  # 30-60s: 10 users\\n            (90, 15),  # 60-90s: 15 users\\n            (120, 20),  # 90-120s: 20 users\\n            (150, 25),  # 120-150s: 25 users\\n            (180, 30),  # 150-180s: 30 users\\n            (210, 35),  # 180-210s: 35 users\\n            (240, 40),  # 210-240s: 40 users\\n            (270, 45),  # 240-270s: 45 users\\n            (300, 50),  # 270-300s: 50 users\\n        ]\\n\\n        for time_limit, user_count in steps:\\n            if run_time < time_limit:\\n                return user_count, 10\\n\\n        return None\\n\\n\\n# Event handlers for metrics\\n_env_bags = {}\\n\\n\\n@events.test_start.add_listener\\ndef on_test_start(environment, **_kwargs):\\n    _env_bags[environment] = {\\\"slow_10s\\\": 0, \\\"slow_20s\\\": 0}\\n\\n\\n@events.request.add_listener\\ndef on_request(request_type, name, response_time, response_length, exception, context, **kwargs):  # noqa: ARG001\\n    \\\"\\\"\\\"Track slow requests using Locust's built-in timing.\\\"\\\"\\\"\\n    # response_time is in milliseconds from Locust\\n    bag = _env_bags.get(context.get(\\\"environment\\\") if context else None)\\n    if bag is None:\\n        # fallback: try the single environment we likely have\\n        if len(_env_bags) == 1:\\n            bag = next(iter(_env_bags.values()))\\n        else:\\n            return\\n\\n    if exception is None:  # Only count successful requests for timing\\n        if response_time > 10_000:  # 10 seconds in ms\\n            bag[\\\"slow_10s\\\"] += 1\\n        if response_time > 20_000:  # 20 seconds in ms\\n            bag[\\\"slow_20s\\\"] += 1\\n\\n\\n@events.test_stop.add_listener\\ndef on_test_stop(environment, **_kwargs):\\n    stats = environment.stats.total\\n    if stats.num_requests == 0:\\n        return\\n\\n    p95 = stats.get_response_time_percentile(0.95) or 0\\n    fail_ratio = stats.fail_ratio\\n    _env_bags.get(environment, {\\\"slow_10s\\\": 0, \\\"slow_20s\\\": 0})\\n\\n    if fail_ratio > 0.05 or p95 > 10_000:\\n        pass\\n    else:\\n        pass\\n\\n    _env_bags.pop(environment, None)\\n\\n\\nclass BaseLangflowUser(FastHttpUser):\\n    abstract = True\\n    REQUEST_TIMEOUT = float(os.getenv(\\\"REQUEST_TIMEOUT\\\", \\\"10\\\"))\\n\\n    def on_start(self):\\n        self.session_id = f\\\"step_{self.__class__.__name__}_{id(self)}_{int(time.time())}\\\"\\n        self.request_count = 0\\n\\n    def make_request(self, message_type=\\\"simple\\\", tag_suffix=\\\"\\\"):\\n        message = TEST_MESSAGES.get(message_type, TEST_MESSAGES[\\\"simple\\\"])\\n        payload = {\\\"input_value\\\": message, \\\"session_id\\\": f\\\"{self.session_id}_{self.request_count}\\\"}\\n        headers = {\\\"x-api-key\\\": API_KEY, \\\"Content-Type\\\": \\\"application/json\\\"}\\n        self.request_count += 1\\n        name = f\\\"{API_ENDPOINT} [{message_type}{tag_suffix}]\\\"\\n\\n        with self.client.post(\\n            API_ENDPOINT,\\n            json=payload,\\n            headers=headers,\\n            name=name,\\n            timeout=self.REQUEST_TIMEOUT,\\n            catch_response=True,\\n        ) as response:\\n            # Handle successful responses\\n            if response.status_code == 200:\\n                try:\\n                    data = response.json()\\n                except json.JSONDecodeError:\\n                    return response.failure(\\\"Invalid JSON response\\\")\\n\\n                # Strictly check for success=True in the response payload\\n                success = data.get(\\\"success\\\")\\n                if success is True:\\n                    return response.success()\\n\\n                # Application-level failure - success is False, None, or missing\\n                msg = str(data.get(\\\"result\\\", \\\"Unknown error\\\"))[:200]\\n                success_status = f\\\"success={success}\\\" if success is not None else \\\"success=missing\\\"\\n                return response.failure(f\\\"Flow failed ({success_status}): {msg}\\\")\\n\\n            if response.status_code in (429, 503):\\n                return response.failure(f\\\"Backpressure: {response.status_code}\\\")\\n            if response.status_code == 401:\\n                return response.failure(\\\"Unauthorized\\\")\\n            if response.status_code == 404:\\n                return response.failure(\\\"Not Found - possible bad FLOW_ID or misconfiguration\\\")\\n            if response.status_code >= 500:\\n                return response.failure(f\\\"Server error {response.status_code}\\\")\\n            return response.failure(f\\\"HTTP {response.status_code}\\\")\\n\\n\\nclass StepTestUser(BaseLangflowUser):\\n    \\\"\\\"\\\"User class for step ramp testing - sends medium complexity requests.\\\"\\\"\\\"\\n\\n    wait_time = between(1, 2)\\n\\n    @task\\n    def step_test(self):\\n        self.make_request(message_type=\\\"medium\\\", tag_suffix=\\\"-step\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/locustfile.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a404e3c28ba62f0e20a4f171d9294bbe4836e6786ee2ab3208d2556e033d67c\",\"content\":\"import os\\nimport time\\nfrom http import HTTPStatus\\n\\nfrom locust import FastHttpUser, between, events, task\\n\\n\\n@events.quitting.add_listener\\ndef _(environment, **_kwargs):\\n    \\\"\\\"\\\"Print stats at test end for analysis.\\\"\\\"\\\"\\n    if environment.stats.total.fail_ratio > 0.01:\\n        environment.process_exit_code = 1\\n    environment.runner.quit()\\n\\n\\nclass FlowRunUser(FastHttpUser):\\n    \\\"\\\"\\\"FlowRunUser simulates users sending requests to the Langflow run endpoint.\\n\\n    Designed for high-load testing with proper wait times and connection handling.\\n    Uses FastHttpUser for better performance with keep-alive connections and connection pooling.\\n\\n    Environment Variables:\\n      - LANGFLOW_HOST: Base URL for the Langflow server (default: http://localhost:7860)\\n      - FLOW_ID: UUID or endpoint name of the flow to test (default: 62c21279-f7ca-43e2-b5e3-326ac573db04)\\n      - API_KEY: API key for authentication, sent as header 'x-api-key' (Required)\\n      - MIN_WAIT: Minimum wait time between requests in ms (default: 2000)\\n      - MAX_WAIT: Maximum wait time between requests in ms (default: 5000)\\n      - REQUEST_TIMEOUT: Timeout for each request in seconds (default: 30.0)\\n    \\\"\\\"\\\"\\n\\n    abstract = False  # This user class can be instantiated\\n    connection_timeout = float(os.getenv(\\\"REQUEST_TIMEOUT\\\", \\\"30.0\\\"))  # Configurable timeout\\n    network_timeout = float(os.getenv(\\\"REQUEST_TIMEOUT\\\", \\\"30.0\\\"))\\n\\n    # Dynamic wait time based on environment variables or defaults\\n    # Increased default minimum wait to reduce database pressure\\n    wait_time = between(\\n        float(os.getenv(\\\"MIN_WAIT\\\", \\\"2000\\\")) / 1000,\\n        float(os.getenv(\\\"MAX_WAIT\\\", \\\"5000\\\")) / 1000,\\n    )\\n\\n    # Use the host provided by environment variable or default\\n    host = os.getenv(\\\"LANGFLOW_HOST\\\", \\\"http://localhost:7860\\\")\\n\\n    # Flow ID from environment variable or default example UUID\\n    flow_id = os.getenv(\\\"FLOW_ID\\\")\\n\\n    def __init__(self, *args, **kwargs) -> None:\\n        super().__init__(*args, **kwargs)\\n        self._last_response: dict | None = None\\n        self._consecutive_failures = 0\\n\\n    def on_start(self):\\n        \\\"\\\"\\\"Setup and validate required configurations.\\\"\\\"\\\"\\n        if not os.getenv(\\\"API_KEY\\\"):\\n            msg = \\\"API_KEY environment variable is required for load testing\\\"\\n            raise ValueError(msg)\\n\\n        # Test connection and auth before starting\\n        with self.client.get(\\\"/health\\\", catch_response=True) as response:\\n            if response.status_code != HTTPStatus.OK:\\n                msg = f\\\"Initial health check failed: {response.status_code}\\\"\\n                raise ConnectionError(msg)\\n\\n    def log_error(self, name: str, exc: Exception, response_time: float):\\n        \\\"\\\"\\\"Helper method to log errors in a format Locust expects.\\n\\n        Args:\\n            name: The name/endpoint of the request\\n            exc: The exception that occurred\\n            response_time: The response time in milliseconds\\n        \\\"\\\"\\\"\\n        # Log error in stats\\n        self.environment.stats.log_error(\\\"ERROR\\\", name, str(exc))\\n        # Log request with error\\n        self.environment.stats.log_request(\\\"ERROR\\\", name, response_time, 0)\\n\\n    @task(1)\\n    def run_flow_endpoint(self):\\n        \\\"\\\"\\\"Sends a POST request to the run endpoint using a realistic payload.\\n\\n        Includes basic error handling.\\n        \\\"\\\"\\\"\\n        if not self.flow_id:\\n            msg = \\\"FLOW_ID environment variable is required for load testing\\\"\\n            raise ValueError(msg)\\n        endpoint = f\\\"/api/v1/run/{self.flow_id}?stream=false\\\"\\n\\n        # Realistic payload that exercises the system\\n        payload = {\\n            \\\"input_value\\\": (\\n                \\\"Hey, Could you check https://docs.langflow.org for me? Later, could you calculate 1390 / 192 ?\\\"\\n            ),\\n            \\\"output_type\\\": \\\"chat\\\",\\n            \\\"input_type\\\": \\\"chat\\\",\\n            \\\"tweaks\\\": {},\\n        }\\n\\n        headers = {\\n            \\\"Content-Type\\\": \\\"application/json\\\",\\n            \\\"x-api-key\\\": os.getenv(\\\"API_KEY\\\"),\\n            \\\"Accept\\\": \\\"application/json\\\",\\n        }\\n\\n        start_time = time.time()\\n        try:\\n            with self.client.post(\\n                endpoint, json=payload, headers=headers, catch_response=True, timeout=self.connection_timeout\\n            ) as response:\\n                response_time = (time.time() - start_time) * 1000\\n                if response.status_code == HTTPStatus.OK:\\n                    try:\\n                        self._last_response = response.json()\\n                    except ValueError as e:\\n                        response.failure(\\\"Invalid JSON response\\\")\\n                        self.log_error(endpoint, e, response_time)\\n                else:\\n                    error_text = response.text or \\\"No response text\\\"\\n                    error_msg = f\\\"Unexpected status code: {response.status_code}, Response: {error_text[:200]}\\\"\\n                    response.failure(error_msg)\\n                    self.log_error(endpoint, Exception(error_msg), response_time)\\n        except Exception as e:\\n            response_time = (time.time() - start_time) * 1000\\n            self.log_error(endpoint, e, response_time)\\n            response.failure(f\\\"Error: {e}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/performance/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/performance/check_key_benchmark.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e0861e15198931af53b0a321dfd9d9c88a825e3bb8778ba370fa5cab294cd2de\",\"content\":\"# src/backend/tests/perf/check_key_benchmark.py\\nimport logging\\nimport statistics\\nimport time\\nimport uuid\\n\\nimport pytest\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.database.models.api_key import crud as api_key_crud\\nfrom langflow.services.database.models.api_key.model import ApiKey\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_settings_service\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nlogger = logging.getLogger(__name__)\\n\\n\\ndef _get_test_password() -> str:\\n    \\\"\\\"\\\"Generate a unique test password for benchmark runs.\\\"\\\"\\\"\\n    return str(uuid.uuid4())\\n\\n\\nclass DummyResult:\\n    def __init__(self, items):\\n        self._items = items\\n\\n    def all(self):\\n        return self._items\\n\\n\\nasync def benchmark_once(\\n    n_keys: int,\\n    iterations: int = 100,\\n    async_db_session: AsyncSession | None = None,\\n):\\n    settings_service = None\\n    try:\\n        settings_service = get_settings_service()\\n    except Exception:\\n        settings_service = None\\n\\n    stored_rows = []\\n    # generate N keys, keep one matching candidate_key to test hit\\n    candidate_raw = f\\\"sk-test-{uuid.uuid4()}\\\"\\n\\n    for i in range(n_keys):\\n        raw = f\\\"sk-test-{uuid.uuid4()}\\\"\\n        if i == n_keys - 1:\\n            raw = candidate_raw\\n        try:\\n            stored = auth_utils.encrypt_api_key(raw, settings_service=settings_service)\\n        except Exception:\\n            stored = f\\\"enc-{raw}\\\"\\n        stored_rows.append((str(i), stored, str(uuid.uuid4())))\\n\\n    if async_db_session is not None:\\n        # use provided async session fixture to mimic DB\\n        db_session = async_db_session\\n        # create a user\\n        user = User(username=f\\\"u-{uuid.uuid4()}\\\", password=_get_test_password())\\n        db_session.add(user)\\n        await db_session.flush()\\n        await db_session.refresh(user)\\n\\n        for i, (_, stored, _uid) in enumerate(stored_rows):\\n            api = ApiKey(api_key=stored, name=f\\\"k-{i}\\\", user_id=user.id)\\n            db_session.add(api)\\n        await db_session.commit()\\n\\n        timings = []\\n        for _ in range(iterations):\\n            t0 = time.perf_counter()\\n            await api_key_crud._check_key_from_db(db_session, candidate_raw, settings_service)\\n            t1 = time.perf_counter()\\n            timings.append((t1 - t0) * 1000.0)  # ms\\n\\n    mean = statistics.mean(timings)\\n    p50 = statistics.median(timings)\\n    total_ms = sum(timings)\\n    return {\\n        \\\"n_keys\\\": n_keys,\\n        \\\"iterations\\\": iterations,\\n        \\\"mean_ms\\\": mean,\\n        \\\"p50_ms\\\": p50,\\n        \\\"total_ms\\\": total_ms,\\n    }\\n\\n\\n@pytest.mark.parametrize(\\\"n_keys\\\", [1, 10, 50, 100, 1000])\\nasync def test_benchmark_check_key_from_db_smoke(async_session: AsyncSession, n_keys):\\n    \\\"\\\"\\\"Run a quick smoke benchmark using simulated stored values (no real crypto).\\n\\n    This test doesn't assert strict performance thresholds \u2014 it ensures the\\n    benchmark runner works under pytest and returns sensible metrics.\\n    \\\"\\\"\\\"\\n    # keep iterations small for CI-friendly run time - use async session fixture\\n    r = await benchmark_once(n_keys=n_keys, iterations=5, async_db_session=async_session)\\n\\n    # basic sanity checks\\n    assert r[\\\"n_keys\\\"] == n_keys\\n    assert r[\\\"mean_ms\\\"] >= 0.0\\n    assert r[\\\"p50_ms\\\"] >= 0.0\\n\\n    # log results so they are captured by pytest's logging capture\\n    logger.info(\\n        \\\"perf n=%s mean=%.2fms p50=%.2fms total=%.2fms\\\",\\n        n_keys,\\n        r[\\\"mean_ms\\\"],\\n        r[\\\"p50_ms\\\"],\\n        r[\\\"total_ms\\\"],\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/performance/test_server_init.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9bcded09356ddec474791e4d07d149d8963aef6455916bfc2f0c27fa4878ebe3\",\"content\":\"import os\\n\\nimport pytest\\nfrom langflow.services.deps import get_settings_service\\n\\n\\n@pytest.fixture(autouse=True)\\ndef setup_database_url(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"Setup a temporary database URL for testing.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    db_path = tmp_path / \\\"test_performance.db\\\"\\n    original_value = os.getenv(\\\"LANGFLOW_DATABASE_URL\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_DATABASE_URL\\\", raising=False)\\n    test_db_url = f\\\"sqlite:///{db_path}\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_DATABASE_URL\\\", test_db_url)\\n    settings_service.set(\\\"database_url\\\", test_db_url)\\n    yield\\n    # Restore original value if it existed\\n    if original_value is not None:\\n        monkeypatch.setenv(\\\"LANGFLOW_DATABASE_URL\\\", original_value)\\n        settings_service.set(\\\"database_url\\\", original_value)\\n    else:\\n        monkeypatch.delenv(\\\"LANGFLOW_DATABASE_URL\\\", raising=False)\\n\\n\\nasync def test_initialize_services():\\n    \\\"\\\"\\\"Benchmark the initialization of services.\\\"\\\"\\\"\\n    from langflow.services.utils import initialize_services\\n\\n    await initialize_services(fix_migration=False)\\n    settings_service = get_settings_service()\\n    assert \\\"test_performance.db\\\" in settings_service.settings.database_url\\n\\n\\ndef test_setup_llm_caching():\\n    \\\"\\\"\\\"Benchmark LLM caching setup.\\\"\\\"\\\"\\n    from langflow.interface.utils import setup_llm_caching\\n\\n    setup_llm_caching()\\n    settings_service = get_settings_service()\\n    assert \\\"test_performance.db\\\" in settings_service.settings.database_url\\n\\n\\nasync def test_initialize_super_user():\\n    \\\"\\\"\\\"Benchmark super user initialization.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import initialize_auto_login_default_superuser\\n    from langflow.services.utils import initialize_services\\n\\n    await initialize_services(fix_migration=False)\\n    await initialize_auto_login_default_superuser()\\n    settings_service = get_settings_service()\\n    assert \\\"test_performance.db\\\" in settings_service.settings.database_url\\n\\n\\nasync def test_get_and_cache_all_types_dict():\\n    \\\"\\\"\\\"Benchmark get_and_cache_all_types_dict function.\\\"\\\"\\\"\\n    from lfx.interface.components import get_and_cache_all_types_dict\\n\\n    settings_service = get_settings_service()\\n    result = await get_and_cache_all_types_dict(settings_service)\\n    assert \\\"vectorstores\\\" in result\\n    assert \\\"test_performance.db\\\" in settings_service.settings.database_url\\n\\n\\nasync def test_create_starter_projects():\\n    \\\"\\\"\\\"Benchmark creation of starter projects.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import create_or_update_starter_projects\\n    from langflow.services.utils import initialize_services\\n    from lfx.interface.components import get_and_cache_all_types_dict\\n\\n    await initialize_services(fix_migration=False)\\n    settings_service = get_settings_service()\\n    types_dict = await get_and_cache_all_types_dict(settings_service)\\n    await create_or_update_starter_projects(types_dict)\\n    assert \\\"test_performance.db\\\" in settings_service.settings.database_url\\n\\n\\nasync def test_load_flows():\\n    \\\"\\\"\\\"Benchmark loading flows from directory.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import load_flows_from_directory\\n\\n    await load_flows_from_directory()\\n    settings_service = get_settings_service()\\n    assert \\\"test_performance.db\\\" in settings_service.settings.database_url\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/stress/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"419b8badc2efb06f767c34669ac6cf308e2f6104b0bd66eadbeb257be7a7c044\",\"content\":\"# Telemetry write stress test\\n\\n`stress_telemetry_writes.py` is a manual harness for reproducing the\\n\\\"transactions + vertex_builds eat the DB pool\\\" failure mode and verifying\\nfixes against it.\\n\\nIt bypasses the FastAPI / locust / flow-execution layer and hammers\\n`transaction_service.log_transaction()` and `lfx.graph.utils.log_vertex_build()`\\ndirectly from many concurrent coroutines, which mirrors what the per-vertex\\n`BackgroundTasks` workers do during heavy flow load (but without needing an\\nOpenAI key or a real flow to run).\\n\\n## Run against SQLite\\n\\n```bash\\nuv run python src/backend/tests/stress/stress_telemetry_writes.py \\\\\\n    --concurrency 200 --seconds 15\\n```\\n\\n## Run against Postgres\\n\\n```bash\\n# Start a throwaway Postgres\\ndocker run --rm -d --name langflow-pg-test -p 55432:5432 \\\\\\n    -e POSTGRES_PASSWORD=langflow -e POSTGRES_USER=langflow \\\\\\n    -e POSTGRES_DB=langflow postgres:16\\n\\nexport DB_URL=\\\"postgresql+psycopg://langflow:langflow@localhost:55432/langflow\\\"  # pragma: allowlist secret\\n# (or any standard postgres DSN, e.g. \\\"$LANGFLOW_DATABASE_URL\\\" if set)\\nuv run python src/backend/tests/stress/stress_telemetry_writes.py \\\\\\n    --concurrency 200 --seconds 15\\n```\\n\\n## Toggle the writer off to reproduce the legacy failure mode\\n\\n```bash\\nLANGFLOW_TELEMETRY_WRITER_ENABLED=false \\\\\\nLANGFLOW_DB_CONNECTION_SETTINGS='{\\\"pool_size\\\":5,\\\"max_overflow\\\":5,\\\"pool_timeout\\\":3}' \\\\\\n    uv run python src/backend/tests/stress/stress_telemetry_writes.py \\\\\\n        --concurrency 500 --seconds 15\\n```\\n\\n## What to look for\\n- `error_total=0` \u2014 neither SQLite \\\"database is locked\\\" nor Postgres\\n  pool-timeout exceptions should fire when the writer is enabled.\\n- `enq_tx` / `enq_vb` counters match producer success counts.\\n- After a sufficient drain grace, the DB row counts should match the\\n  enqueued counts (modulo retention).\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/stress/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/stress/stress_telemetry_writes.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3c9ce728a69efe478b6368d07c08a9cb4b3e950c595f1a976f716bfdb1a692b9\",\"content\":\"r\\\"\\\"\\\"Direct stress harness for transaction + vertex_build writes.\\n\\nBypasses FastAPI / locust / OpenAI by calling the same write functions the\\ngraph executor invokes via BackgroundTasks. Reproduces the failure mode the\\nuser reported (SQLite \\\"database is locked\\\" and Postgres pool timeouts) by\\nrunning many concurrent writers against the configured database.\\n\\nUsage:\\n    uv run python src/backend/tests/stress/stress_telemetry_writes.py \\\\\\n        --concurrency 200 --seconds 30\\n\\n    DB_URL=$LANGFLOW_DATABASE_URL \\\\\\n    uv run python src/backend/tests/stress/stress_telemetry_writes.py \\\\\\n        --concurrency 500 --seconds 30\\n\\nSee README.md for full usage and what numbers to interpret.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport asyncio\\nimport os\\nimport random\\nimport sys\\nimport time\\nimport traceback\\nfrom collections import Counter\\nfrom uuid import uuid4\\n\\n# Configure env BEFORE importing langflow so settings pick up the DB URL.\\nDB_URL = os.environ.get(\\\"DB_URL\\\", \\\"sqlite:///./stress.db\\\")\\nos.environ.setdefault(\\\"LANGFLOW_DATABASE_URL\\\", DB_URL)\\nos.environ.setdefault(\\\"LANGFLOW_TRANSACTIONS_STORAGE_ENABLED\\\", \\\"true\\\")\\nos.environ.setdefault(\\\"LANGFLOW_VERTEX_BUILDS_STORAGE_ENABLED\\\", \\\"true\\\")\\n# Auto-login keeps service init from blocking on user setup paths.\\nos.environ.setdefault(\\\"LANGFLOW_AUTO_LOGIN\\\", \\\"true\\\")\\n\\n\\nasync def setup() -> tuple[object, object]:\\n    from langflow.services.deps import get_db_service, get_settings_service\\n    from langflow.services.manager import get_service_manager\\n    from langflow.services.utils import initialize_services\\n\\n    settings = get_settings_service().settings\\n    print(f\\\"[setup] DB_URL={settings.database_url}\\\")\\n    print(f\\\"[setup] telemetry_writer_enabled={getattr(settings, 'telemetry_writer_enabled', 'n/a')}\\\")\\n    await initialize_services()\\n    db_service = get_db_service()\\n    await db_service.initialize_alembic_log_file()\\n    await db_service.create_db_and_tables()\\n\\n    if getattr(settings, \\\"telemetry_writer_enabled\\\", False):\\n        from langflow.services.deps import get_telemetry_writer_service\\n\\n        writer = get_telemetry_writer_service()\\n        if writer is not None and writer.is_enabled():\\n            await writer.start()\\n            print(f\\\"[setup] telemetry_writer started, running={writer.is_running()}\\\")\\n    return db_service, get_service_manager()\\n\\n\\ndef make_inputs(i: int) -> dict:\\n    return {\\n        \\\"input_value\\\": f\\\"hello {i} {'x' * 200}\\\",\\n        \\\"config\\\": {\\\"temperature\\\": 0.7, \\\"model\\\": \\\"gpt-4o-mini\\\"},\\n    }\\n\\n\\ndef make_outputs(i: int) -> dict:\\n    return {\\n        \\\"result\\\": {\\\"text\\\": f\\\"answer {i} \\\" + (\\\"y\\\" * 400), \\\"tokens\\\": 123},\\n        \\\"trace_id\\\": str(uuid4()),\\n    }\\n\\n\\nasync def worker(\\n    worker_id: int,\\n    flow_id: str,\\n    stop_at: float,\\n    counters: Counter,\\n    error_samples: dict[str, str],\\n) -> None:\\n    from lfx.graph.utils import log_vertex_build\\n    from lfx.services.deps import get_transaction_service\\n\\n    tx_service = get_transaction_service()\\n    i = 0\\n    while time.monotonic() < stop_at:\\n        i += 1\\n        try:\\n            await tx_service.log_transaction(\\n                flow_id=flow_id,\\n                vertex_id=f\\\"vertex-{worker_id}-{i % 5}\\\",\\n                inputs=make_inputs(i),\\n                outputs=make_outputs(i),\\n                status=\\\"success\\\",\\n                target_id=f\\\"target-{worker_id}-{i % 5}\\\",\\n            )\\n            counters[\\\"transactions_ok\\\"] += 1\\n        except Exception as exc:\\n            key = f\\\"tx:{type(exc).__name__}\\\"\\n            counters[key] += 1\\n            error_samples.setdefault(key, f\\\"{exc!s}\\\\n{traceback.format_exc(limit=2)}\\\")\\n\\n        try:\\n            await log_vertex_build(\\n                flow_id=flow_id,\\n                vertex_id=f\\\"vertex-{worker_id}-{i % 5}\\\",\\n                valid=True,\\n                params=str(make_inputs(i)),\\n                data=make_outputs(i),\\n                artifacts=None,\\n            )\\n            counters[\\\"vertex_builds_ok\\\"] += 1\\n        except Exception as exc:\\n            key = f\\\"vb:{type(exc).__name__}\\\"\\n            counters[key] += 1\\n            error_samples.setdefault(key, f\\\"{exc!s}\\\\n{traceback.format_exc(limit=2)}\\\")\\n\\n        await asyncio.sleep(random.uniform(0.0, 0.01))\\n\\n\\nasync def count_rows(db_service) -> tuple[int, int]:\\n    from sqlalchemy import text\\n\\n    async with db_service.engine.begin() as conn:\\n        tx = (await conn.execute(text('SELECT count(*) FROM \\\"transaction\\\"'))).scalar_one()\\n        vb = (await conn.execute(text('SELECT count(*) FROM \\\"vertex_build\\\"'))).scalar_one()\\n    return int(tx), int(vb)\\n\\n\\ndef _print_writer_state(label: str, writer) -> None:\\n    print(\\n        f\\\"[run]  writer @ {label}: \\\"\\n        f\\\"enq_tx={writer.enqueued_transactions} enq_vb={writer.enqueued_vertex_builds} \\\"\\n        f\\\"flushed_rows={writer.flushed_rows} failed_batches={writer.failed_batches} \\\"\\n        f\\\"dropped_tx={writer.dropped_transactions} dropped_vb={writer.dropped_vertex_builds} \\\"\\n        f\\\"tx_buffer={len(writer._tx_buffer)} vb_buffer={len(writer._vb_buffer)}\\\"\\n    )\\n\\n\\nasync def main_async(args) -> int:\\n    db_service, service_manager = await setup()\\n    flow_id = str(uuid4())\\n    counters: Counter = Counter()\\n    error_samples: dict[str, str] = {}\\n\\n    print(f\\\"[run]  concurrency={args.concurrency}  seconds={args.seconds}  flow={flow_id}\\\")\\n    pre_tx, pre_vb = await count_rows(db_service)\\n    print(f\\\"[run]  pre-rows tx={pre_tx} vb={pre_vb}\\\")\\n\\n    start = time.monotonic()\\n    stop_at = start + args.seconds\\n    workers = [\\n        asyncio.create_task(worker(i, flow_id, stop_at, counters, error_samples)) for i in range(args.concurrency)\\n    ]\\n    results = await asyncio.gather(*workers, return_exceptions=True)\\n    elapsed = time.monotonic() - start\\n    exc_types: Counter = Counter()\\n    for r in results:\\n        if isinstance(r, BaseException):\\n            exc_types[type(r).__name__] += 1\\n            error_samples.setdefault(\\n                f\\\"worker:{type(r).__name__}\\\",\\n                f\\\"{r!s}\\\\n{''.join(traceback.format_exception(r))[-200:]}\\\",\\n            )\\n    if exc_types:\\n        print(f\\\"[run]  worker-level exceptions: {dict(exc_types)}\\\")\\n\\n    writer = None\\n    try:\\n        from langflow.services.deps import get_telemetry_writer_service\\n\\n        writer = get_telemetry_writer_service()\\n    except Exception:\\n        writer = None\\n    if writer is not None and writer.is_running():\\n        _print_writer_state(\\\"workers-done\\\", writer)\\n\\n    drain_grace = float(os.environ.get(\\\"DRAIN_GRACE_S\\\", \\\"5\\\"))\\n    if drain_grace > 0:\\n        print(f\\\"[run]  drain grace {drain_grace}s ...\\\")\\n        await asyncio.sleep(drain_grace)\\n\\n    if writer is not None and writer.is_running():\\n        _print_writer_state(\\\"post-drain\\\", writer)\\n\\n    post_tx, post_vb = await count_rows(db_service)\\n    print()\\n    print(f\\\"[done] elapsed={elapsed:.2f}s\\\")\\n    print(f\\\"[done] counters: {dict(counters)}\\\")\\n    print(f\\\"[done] rows tx: pre={pre_tx} post={post_tx} delta={post_tx - pre_tx}\\\")\\n    print(f\\\"[done] rows vb: pre={pre_vb} post={post_vb} delta={post_vb - pre_vb}\\\")\\n    if error_samples:\\n        print(\\\"[done] error samples:\\\")\\n        for key, sample in list(error_samples.items())[:10]:\\n            print(f\\\"  --- {key} ---\\\")\\n            for line in sample.splitlines()[:6]:\\n                print(f\\\"    {line}\\\")\\n\\n    try:\\n        await service_manager.teardown()\\n    except Exception as exc:\\n        print(f\\\"[teardown] error: {exc}\\\")\\n\\n    errs = sum(v for k, v in counters.items() if not k.endswith(\\\"_ok\\\"))\\n    print(f\\\"[done] error_total={errs}\\\")\\n    return 1 if errs > 0 else 0\\n\\n\\ndef main() -> int:\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\\"--concurrency\\\", type=int, default=200, help=\\\"Number of concurrent worker coroutines.\\\")\\n    parser.add_argument(\\\"--seconds\\\", type=int, default=20, help=\\\"Producer phase duration in seconds.\\\")\\n    args = parser.parse_args()\\n    return asyncio.run(main_async(args))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    sys.exit(main())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/test_migrations/001_bad_expand.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3f8d96f4eb8029dc5c1d29085ae528f0449065642cda6bfdb3e9f5318a8c7c71\",\"content\":\"\\\"\\\"\\\"Test migration - BAD EXPAND phase.\\n\\nThis should fail validation.\\n\\nRevision ID: test001\\n\\\"\\\"\\\"  # noqa: N999\\n\\nimport sqlalchemy as sa\\nfrom alembic import op\\n\\nrevision = \\\"test001\\\"\\ndown_revision = None\\n\\n\\ndef upgrade():\\n    # \u274c Bad: non-nullable column without default\\n    op.add_column(\\\"users\\\", sa.Column(\\\"email_verified\\\", sa.Boolean(), nullable=False))\\n\\n    # \u274c Bad: dropping column in EXPAND phase\\n    op.drop_column(\\\"users\\\", \\\"old_field\\\")\\n\\n\\ndef downgrade():\\n    pass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/test_migrations/002_good_expand.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e84b5d32af4230c9be25f9add8da07df6fd1611feb744f9619eb933a5627b993\",\"content\":\"\\\"\\\"\\\"Test migration - GOOD EXPAND phase.\\n\\nPhase: EXPAND\\nSafe to rollback: YES\\n\\nRevision ID: test002\\n\\\"\\\"\\\"  # noqa: N999\\n\\nimport sqlalchemy as sa\\nfrom alembic import op\\n\\nrevision = \\\"test002\\\"\\ndown_revision = None\\n\\n\\ndef upgrade():\\n    \\\"\\\"\\\"EXPAND PHASE: Add new columns.\\\"\\\"\\\"\\n    bind = op.get_bind()\\n    inspector = sa.inspect(bind)\\n    columns = [col[\\\"name\\\"] for col in inspector.get_columns(\\\"users\\\")]\\n\\n    # \u2705 Good: nullable column with existence check\\n    if \\\"email_verified\\\" not in columns:\\n        op.add_column(\\\"users\\\", sa.Column(\\\"email_verified\\\", sa.Boolean(), nullable=True, server_default=\\\"false\\\"))\\n\\n\\ndef downgrade():\\n    bind = op.get_bind()\\n    inspector = sa.inspect(bind)\\n    columns = [col[\\\"name\\\"] for col in inspector.get_columns(\\\"users\\\")]\\n\\n    if \\\"email_verified\\\" in columns:\\n        op.drop_column(\\\"users\\\", \\\"email_verified\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/test_migrations/003_bad_contract.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"88c9d5221319795d538ab10dab02862fb3098dba6f8d16c20ccd9314acaffc62\",\"content\":\"\\\"\\\"\\\"Test migration - BAD CONTRACT phase.\\n\\nPhase: CONTRACT\\n\\nRevision ID: test003\\n\\\"\\\"\\\"  # noqa: N999\\n\\nimport sqlalchemy as sa\\nfrom alembic import op\\n\\nrevision = \\\"test003\\\"\\ndown_revision = None\\n\\n\\ndef upgrade():\\n    # \u274c Bad: No verification before dropping\\n    op.drop_column(\\\"users\\\", \\\"old_email\\\")\\n\\n    # \u274c Bad: Adding new column in CONTRACT phase\\n    op.add_column(\\\"users\\\", sa.Column(\\\"new_field\\\", sa.String()))\\n\\n\\ndef downgrade():\\n    pass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/test_migrations/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/test_starter_projects.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2a918d8ec95edddbad05bd0e675d8a65fa4720af3b4e3549a2d0babdc2a319e0\",\"content\":\"\\\"\\\"\\\"Test suite for starter project JSON files.\\n\\nVerifies that starter project JSON files are properly structured and that:\\n- noteNode types have width/height at the root level\\n- Other node types have width/height removed from root level\\n- Agent nodes never ship with the legacy one-line prompt that QA flagged\\n  during the structured-default rollout\\n- Agent nodes that previously had purpose-specific instructions (e.g.\\n  Market Research, SaaS Pricing) do not regress to the generic default\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.base.agents.default_system_prompt import DEFAULT_SYSTEM_PROMPT_TEMPLATE\\n\\nSTARTER_PROJECTS_DIR = Path(__file__).parent.parent / \\\"base\\\" / \\\"langflow\\\" / \\\"initial_setup\\\" / \\\"starter_projects\\\"\\nBUNDLE_STARTER_PROJECTS_DIR = Path(__file__).parents[2] / \\\"bundles\\\"\\nLOCALES_EN_FILE = Path(__file__).parent.parent / \\\"base\\\" / \\\"langflow\\\" / \\\"locales\\\" / \\\"en.json\\\"\\n\\n# QA observed this exact legacy text in starter project Agents on the cz/default-sys-prompt branch.\\nLEGACY_AGENT_SYSTEM_PROMPT = \\\"You are a helpful assistant that can use tools to answer questions and perform tasks.\\\"\\nAGENT_NODE_TYPES = (\\\"Agent\\\", \\\"ToolCallingAgent\\\")\\nREMOVED_STARTER_PROJECTS = {\\n    \\\"Invoice Summarizer.json\\\",\\n    \\\"Nvidia Remix.json\\\",\\n    \\\"Pok\u00e9dex Agent.json\\\",\\n    \\\"Search agent.json\\\",\\n}\\nRENAMED_STARTER_PROJECTS = {\\n    \\\"Basic Prompt Chaining.json\\\": \\\"Multi Agent Flow.json\\\",\\n    \\\"News Aggregator.json\\\": \\\"Content Aggregator.json\\\",\\n    \\\"Research Agent.json\\\": \\\"Deep Research Agent.json\\\",\\n}\\nBLOCKED_MODEL_OPTION_NAMES = {\\\"gpt-image-2\\\", \\\"gemini-3.1-flash-lite-preview\\\"}\\nBLOCKED_MODEL_OPTION_PREFIXES = (\\\"ibm/mock-\\\",)\\n\\n# Templates whose Agents must keep purpose-specific Agent Instructions (not the\\n# generic DEFAULT_SYSTEM_PROMPT_TEMPLATE). Regression guard for #12855: that PR\\n# replaced every starter Agent's system_prompt.value with the new structured\\n# default, wiping the role-specific prompts these flows depend on. Each entry\\n# pairs (starter project filename, agent node id) with a substring that must\\n# appear in the agent's system_prompt.value.\\nTEMPLATES_WITH_CUSTOM_AGENT_PROMPTS: dict[tuple[str, str], str] = {\\n    (\\\"Instagram Copywriter.json\\\", \\\"Agent-caption\\\"): \\\"expert Instagram copywriter\\\",\\n    (\\\"Market Research.json\\\", \\\"Agent-Hz2it\\\"): \\\"expert business research agent\\\",\\n    (\\\"Content Aggregator.json\\\", \\\"Agent-ZH2Rd\\\"): \\\"content aggregator\\\",\\n    (\\\"Deep Research Agent.json\\\", \\\"Agent-mIgZ5\\\"): \\\"research analyst with access to Tavily Search\\\",\\n    (\\\"SaaS Pricing.json\\\", \\\"Agent-Zm0pK\\\"): \\\"calculate the price\\\",\\n    (\\\"Travel Planning Agents.json\\\", \\\"Agent-v7SnN\\\"): \\\"knowledgeable Local Expert\\\",\\n    (\\\"Travel Planning Agents.json\\\", \\\"Agent-1ON2c\\\"): \\\"Amazing Travel Concierge\\\",\\n    (\\\"Youtube Analysis.json\\\", \\\"Agent-s4EYR\\\"): \\\"comprehensive YouTube video analysis\\\",\\n}\\n\\n\\ndef get_starter_project_files() -> list[Path]:\\n    \\\"\\\"\\\"Get all starter project JSON files.\\\"\\\"\\\"\\n    if not STARTER_PROJECTS_DIR.exists():\\n        msg = f\\\"Starter projects directory not found: {STARTER_PROJECTS_DIR}\\\"\\n        raise FileNotFoundError(msg) from None\\n\\n    json_files = sorted(\\n        [\\n            *STARTER_PROJECTS_DIR.glob(\\\"*.json\\\"),\\n            *BUNDLE_STARTER_PROJECTS_DIR.glob(\\\"**/starter_projects/*.json\\\"),\\n        ]\\n    )\\n    if not json_files:\\n        msg = f\\\"No JSON files found in {STARTER_PROJECTS_DIR}\\\"\\n        raise FileNotFoundError(msg) from None\\n\\n    return json_files\\n\\n\\ndef get_starter_project_path(filename: str) -> Path:\\n    \\\"\\\"\\\"Return the unique core or bundle-owned starter project path.\\\"\\\"\\\"\\n    matches = [path for path in get_starter_project_files() if path.name == filename]\\n    assert len(matches) == 1, f\\\"Expected one starter template named {filename!r}, found {matches}\\\"\\n    return matches[0]\\n\\n\\ndef load_json_file(json_file: Path) -> dict:\\n    \\\"\\\"\\\"Load and parse a JSON file.\\\"\\\"\\\"\\n    try:\\n        with json_file.open(encoding=\\\"utf-8\\\") as f:\\n            return json.load(f)\\n    except json.JSONDecodeError as e:\\n        msg = f\\\"Invalid JSON in {json_file.name}: {e}\\\"\\n        raise ValueError(msg) from e\\n    except Exception as e:\\n        msg = f\\\"Error reading {json_file.name}: {e}\\\"\\n        raise OSError(msg) from e\\n\\n\\ndef iter_dicts(value):\\n    \\\"\\\"\\\"Yield every dict nested inside a parsed starter JSON structure.\\\"\\\"\\\"\\n    if isinstance(value, dict):\\n        yield value\\n        for nested in value.values():\\n            yield from iter_dicts(nested)\\n    elif isinstance(value, list):\\n        for nested in value:\\n            yield from iter_dicts(nested)\\n\\n\\ndef model_option_name(option) -> str | None:\\n    if isinstance(option, str):\\n        return option\\n    if isinstance(option, dict) and isinstance(option.get(\\\"name\\\"), str):\\n        return option[\\\"name\\\"]\\n    return None\\n\\n\\ndef is_blocked_model_option(name: str) -> bool:\\n    return name in BLOCKED_MODEL_OPTION_NAMES or name.startswith(BLOCKED_MODEL_OPTION_PREFIXES)\\n\\n\\ndef test_removed_and_renamed_starter_inventory():\\n    \\\"\\\"\\\"Starter inventory should not keep loading removed or renamed templates from disk.\\\"\\\"\\\"\\n    shipped = {path.name for path in get_starter_project_files()}\\n\\n    assert not REMOVED_STARTER_PROJECTS & shipped\\n    for old_name, new_name in RENAMED_STARTER_PROJECTS.items():\\n        assert old_name not in shipped\\n        assert new_name in shipped\\n\\n\\n@pytest.mark.parametrize(\\\"json_file\\\", get_starter_project_files(), ids=lambda f: f.name)\\nclass TestStarterProjects:\\n    \\\"\\\"\\\"Test suite for all starter project JSON files.\\\"\\\"\\\"\\n\\n    def test_json_validity(self, json_file: Path):\\n        \\\"\\\"\\\"Test that JSON file is valid and can be parsed.\\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        assert isinstance(data, dict), f\\\"{json_file.name} should be a valid JSON object\\\"\\n\\n    def test_prompt_custom_fields_are_materialized(self, json_file: Path):\\n        \\\"\\\"\\\"Prompt variables declared in custom_fields must exist in the serialized template.\\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        missing_fields: list[str] = []\\n\\n        for node in data.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n            node_data = node.get(\\\"data\\\", {}) or {}\\n            node_config = node_data.get(\\\"node\\\", {}) or {}\\n            template = node_config.get(\\\"template\\\", {}) or {}\\n            custom_fields = node_config.get(\\\"custom_fields\\\", {}) or {}\\n\\n            for field_names in custom_fields.values():\\n                if not isinstance(field_names, list):\\n                    continue\\n                for field_name in field_names:\\n                    if field_name not in template:\\n                        node_id = node_data.get(\\\"id\\\", node.get(\\\"id\\\", \\\"<unknown>\\\"))\\n                        missing_fields.append(f\\\"{node_id}.{field_name}\\\")\\n\\n        assert not missing_fields, (\\n            f\\\"{json_file.name}: custom prompt fields are missing from the serialized node template: {missing_fields}\\\"\\n        )\\n\\n    def test_width_height_at_node_level(self, json_file: Path):\\n        \\\"\\\"\\\"Test that width/height are removed from node root level for all node types EXCEPT noteNode.\\n\\n        noteNode type SHOULD have width/height at root level.\\n        Other node types should NOT have width/height at root level.\\n        \\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        nodes = data[\\\"data\\\"][\\\"nodes\\\"]\\n\\n        issues = []\\n\\n        for node_idx, node in enumerate(nodes):\\n            node_type = node.get(\\\"type\\\", \\\"unknown\\\")\\n            node_id = node.get(\\\"id\\\", \\\"UNKNOWN\\\")\\n\\n            # noteNode SHOULD have width/height at root level - skip checking these\\n            if node_type == \\\"noteNode\\\":\\n                continue\\n\\n            # For non-noteNode types, width/height should NOT exist at node level\\n            if \\\"width\\\" in node:\\n                issues.append(\\n                    f\\\"Node {node_idx} (ID: {node_id}, type: {node_type}): \\\"\\n                    f\\\"'width' found at node root level (value: {node['width']}) - \\\"\\n                    f\\\"should be removed for non-noteNode types\\\"\\n                )\\n\\n            if \\\"height\\\" in node:\\n                issues.append(\\n                    f\\\"Node {node_idx} (ID: {node_id}, type: {node_type}): \\\"\\n                    f\\\"'height' found at node root level (value: {node['height']}) - \\\"\\n                    f\\\"should be removed for non-noteNode types\\\"\\n                )\\n\\n        assert not issues, f\\\"{json_file.name}: Width/height issues found:\\\\n\\\" + \\\"\\\\n\\\".join(issues)\\n\\n    def test_agent_nodes_do_not_use_legacy_system_prompt(self, json_file: Path):\\n        \\\"\\\"\\\"Agent nodes must not ship with the legacy one-line system prompt.\\n\\n        Background: PR #12855 introduced a structured 7-section\\n        DEFAULT_SYSTEM_PROMPT_TEMPLATE to replace the old one-line\\n        \\\"You are a helpful assistant...\\\" default. The original version of\\n        this test asserted that every Agent in every starter project use\\n        the new DEFAULT_SYSTEM_PROMPT_TEMPLATE \u2014 that assertion caused a\\n        regression: starter projects with purpose-specific Agent\\n        Instructions (Market Research, SaaS Pricing, etc.) had\\n        their custom prompts overwritten by the generic default to keep\\n        the test green.\\n\\n        New contract: ship the generic default OR a template-specific\\n        prompt, but never the legacy one-liner. A separate parametrised\\n        test (test_agent_keeps_template_specific_prompt) guards the\\n        specific templates that must keep their custom instructions.\\n        \\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        nodes = data.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])\\n\\n        legacy_offenders: list[str] = []\\n\\n        for node in nodes:\\n            node_data = node.get(\\\"data\\\", {}) or {}\\n            node_type = node_data.get(\\\"type\\\", \\\"\\\")\\n            if node_type not in AGENT_NODE_TYPES:\\n                continue\\n\\n            template = node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {}) or {}\\n            system_prompt_field = template.get(\\\"system_prompt\\\", {}) or {}\\n            value = system_prompt_field.get(\\\"value\\\", \\\"\\\")\\n            node_id = node_data.get(\\\"id\\\", \\\"<unknown>\\\")\\n\\n            if value.strip() == LEGACY_AGENT_SYSTEM_PROMPT:\\n                legacy_offenders.append(f\\\"{node_id} ({node_type})\\\")\\n\\n        assert not legacy_offenders, (\\n            f\\\"{json_file.name}: Agent nodes still use the legacy one-line system prompt: \\\"\\n            f\\\"{legacy_offenders}. Use DEFAULT_SYSTEM_PROMPT_TEMPLATE or a template-specific prompt.\\\"\\n        )\\n\\n    def test_model_options_do_not_ship_removed_or_internal_models(self, json_file: Path):\\n        \\\"\\\"\\\"Starter model pickers should not expose non-text or internal mock models.\\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        offenders: list[str] = []\\n\\n        for node_dict in iter_dicts(data):\\n            options = node_dict.get(\\\"options\\\")\\n            if not isinstance(options, list):\\n                continue\\n\\n            for option in options:\\n                name = model_option_name(option)\\n                if name and is_blocked_model_option(name):\\n                    offenders.append(name)\\n\\n        assert not offenders, f\\\"{json_file.name}: blocked model options found: {sorted(set(offenders))}\\\"\\n\\n    def test_ollama_base_url_uses_current_metadata(self, json_file: Path):\\n        \\\"\\\"\\\"Serialized Language Model fields should match the current Ollama URL input shape.\\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        fields = [field for field in iter_dicts(data) if field.get(\\\"name\\\") == \\\"ollama_base_url\\\"]\\n\\n        for field in fields:\\n            assert field.get(\\\"_input_type\\\") == \\\"StrInput\\\"\\n            assert field.get(\\\"input_types\\\") == []\\n            assert field.get(\\\"type\\\") == \\\"str\\\"\\n            assert field.get(\\\"info\\\") == \\\"Endpoint of the Ollama API (Ollama only)\\\"\\n            assert field.get(\\\"value\\\") == \\\"\\\"\\n\\n    def test_knowledge_base_selectors_do_not_ship_fixture_defaults(self, json_file: Path):\\n        \\\"\\\"\\\"Knowledge selectors should start empty instead of pointing at local test fixture names.\\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        offenders = [\\n            field.get(\\\"value\\\")\\n            for field in iter_dicts(data)\\n            if field.get(\\\"name\\\") == \\\"knowledge_base\\\" and field.get(\\\"value\\\")\\n        ]\\n\\n        assert not offenders, f\\\"{json_file.name}: knowledge_base defaults should be empty, got {offenders}\\\"\\n\\n    def test_note_i18n_keys_match_embedded_english_text(self, json_file: Path):\\n        \\\"\\\"\\\"English note translations must not overwrite refreshed README text with stale copy.\\\"\\\"\\\"\\n        data = load_json_file(json_file)\\n        en_locale = load_json_file(LOCALES_EN_FILE)\\n        mismatches: list[str] = []\\n\\n        for node_dict in iter_dicts(data):\\n            i18n_key = node_dict.get(\\\"i18n_key\\\")\\n            description = node_dict.get(\\\"description\\\")\\n            if not isinstance(i18n_key, str) or not isinstance(description, str) or i18n_key not in en_locale:\\n                continue\\n            if en_locale[i18n_key] != description:\\n                mismatches.append(i18n_key)\\n\\n        assert not mismatches, f\\\"{json_file.name}: stale English note i18n keys found: {mismatches}\\\"\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"template_file\\\", \\\"agent_id\\\", \\\"required_substring\\\"),\\n    [\\n        (filename, agent_id, substring)\\n        for (filename, agent_id), substring in TEMPLATES_WITH_CUSTOM_AGENT_PROMPTS.items()\\n    ],\\n    ids=lambda v: v if isinstance(v, str) else repr(v),\\n)\\ndef test_agent_keeps_template_specific_prompt(template_file: str, agent_id: str, required_substring: str):\\n    \\\"\\\"\\\"Templates with purpose-specific Agent Instructions must not regress to the generic default.\\n\\n    Regression guard for #12855: that PR's auto-bake replaced every starter\\n    Agent's system_prompt.value with DEFAULT_SYSTEM_PROMPT_TEMPLATE,\\n    silently dropping role-specific prompts (Market Research's business\\n    researcher, SaaS Pricing's calculation guidance, etc.). The flows that depend on\\n    those instructions broke at runtime. If you legitimately need to\\n    change one of these prompts, update the substring in\\n    TEMPLATES_WITH_CUSTOM_AGENT_PROMPTS in the same change.\\n    \\\"\\\"\\\"\\n    path = get_starter_project_path(template_file)\\n\\n    data = load_json_file(path)\\n    for node in data.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        node_data = node.get(\\\"data\\\", {}) or {}\\n        if node_data.get(\\\"id\\\") != agent_id:\\n            continue\\n        template = node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {}) or {}\\n        value = (template.get(\\\"system_prompt\\\", {}) or {}).get(\\\"value\\\", \\\"\\\")\\n        assert value != DEFAULT_SYSTEM_PROMPT_TEMPLATE, (\\n            f\\\"{template_file}: agent {agent_id} regressed to DEFAULT_SYSTEM_PROMPT_TEMPLATE; \\\"\\n            f\\\"restore the template-specific Agent Instructions containing {required_substring!r}.\\\"\\n        )\\n        assert required_substring in value, (\\n            f\\\"{template_file}: agent {agent_id} system_prompt does not contain expected \\\"\\n            f\\\"substring {required_substring!r}. Got: {value[:120]!r}...\\\"\\n        )\\n        return\\n    pytest.fail(f\\\"{template_file}: agent node {agent_id!r} not found\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4ac11271ec2ba9b3250aa241939f85a194f6ad4318495b7ee4a28097e6ad6131\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9df7ebc71d06f76b807c8f1ce4a919af042c321650e71ae78ec095caf826cc42\",\"content\":\"\\\"\\\"\\\"Tests for agentic features.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_assistant_api_report_repro.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9392e1db3d2039965419b95c7bb1e2ae530733197575937712c239f6fcefa086\",\"content\":\"\\\"\\\"\\\"Reproduction tests for the F2 Langflow Assistant API bug report (2026-06-02).\\n\\nEach test pins the CURRENT behavior of a reported issue so the fix has a\\nfailing test to flip:\\n\\n  Issue 1 \u2014 GET /agentic/check-config returns providers:[] / default_*:null\\n            even though configured_providers is populated.\\n  Issue 2 \u2014 POST /agentic/assist runs the LLM (HTTP 200) on an unknown or\\n            cross-user flow_id instead of rejecting with 404/403.\\n  Issue 3 \u2014 POST /agentic/execute/LangflowAssistant returns HTTP 500 for a\\n            valid assistant flow file (missing provider/model context).\\n\\nThe endpoint tests need at least one configured provider; OPENAI_API_KEY from\\nthe repo .env (loaded by conftest) enables OpenAI for every user, so they skip\\ncleanly when no key is present.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom lfx.services.deps import session_scope\\n\\nfrom tests.api_keys import has_api_key\\n\\n_NEEDS_KEY = pytest.mark.skipif(\\n    not has_api_key(\\\"OPENAI_API_KEY\\\"),\\n    reason=\\\"A configured provider (OPENAI_API_KEY) is required to reach these paths\\\",\\n)\\n\\n\\ndef test_registry_language_model_type_filter_excludes_every_llm():\\n    \\\"\\\"\\\"Issue 1 root cause: language models carry model_type='llm', not 'language'.\\\"\\\"\\\"\\n    from lfx.base.models.unified_models import get_unified_models_detailed\\n\\n    providers = [\\\"OpenAI\\\", \\\"Anthropic\\\"]\\n    as_llm = get_unified_models_detailed(providers=providers, model_type=\\\"llm\\\")\\n    as_language = get_unified_models_detailed(providers=providers, model_type=\\\"language\\\")\\n\\n    assert sum(len(p.get(\\\"models\\\", [])) for p in as_llm) > 0\\n    # check-config passes model_type=\\\"language\\\" \u2192 this is why providers[] is empty.\\n    assert sum(len(p.get(\\\"models\\\", [])) for p in as_language) == 0\\n\\n\\n@_NEEDS_KEY\\nasync def test_check_config_providers_are_consistent_with_configured_providers(client, logged_in_headers):\\n    \\\"\\\"\\\"Issue 1: providers[] and default_* must not be empty when a provider is configured.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/agentic/check-config\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    data = response.json()\\n\\n    assert data[\\\"configured_providers\\\"], \\\"expected at least OpenAI from the env key\\\"\\n    assert data[\\\"providers\\\"], f\\\"providers[] empty despite configured_providers={data['configured_providers']}\\\"\\n    assert data[\\\"default_provider\\\"] is not None\\n    assert data[\\\"default_model\\\"] is not None\\n\\n\\n@_NEEDS_KEY\\nasync def test_assist_rejects_unknown_flow_id_before_invoking_the_model(client, logged_in_headers):\\n    \\\"\\\"\\\"Issue 2: an unknown flow_id should be rejected, not silently run on empty context.\\\"\\\"\\\"\\n    body = {\\\"flow_id\\\": \\\"00000000-0000-0000-0000-000000000000\\\", \\\"input_value\\\": \\\"hi\\\"}\\n    response = await client.post(\\\"api/v1/agentic/assist\\\", json=body, headers=logged_in_headers)\\n    assert response.status_code in (403, 404), response.text\\n\\n\\n@_NEEDS_KEY\\nasync def test_assist_rejects_cross_user_flow_id(client, active_user, user_two_api_key):\\n    \\\"\\\"\\\"Issue 2: user B asking against user A's flow_id should be rejected, not run.\\\"\\\"\\\"\\n    flow_id = uuid4()\\n    async with session_scope() as session:\\n        session.add(\\n            Flow(\\n                id=flow_id,\\n                name=f\\\"repro-cross-user-{flow_id}\\\",\\n                user_id=active_user.id,\\n                data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n            )\\n        )\\n        await session.commit()\\n\\n    try:\\n        body = {\\\"flow_id\\\": str(flow_id), \\\"input_value\\\": \\\"what is on my canvas?\\\"}\\n        response = await client.post(\\\"api/v1/agentic/assist\\\", json=body, headers={\\\"x-api-key\\\": user_two_api_key})\\n        assert response.status_code in (403, 404), response.text\\n    finally:\\n        async with session_scope() as session:\\n            stored = await session.get(Flow, flow_id)\\n            if stored:\\n                await session.delete(stored)\\n                await session.commit()\\n\\n\\n@pytest.mark.api_key_required\\n@_NEEDS_KEY\\nasync def test_execute_named_assistant_flow_is_graceful_not_500(client, logged_in_headers):\\n    \\\"\\\"\\\"Issue 3: executing the built-in assistant flow must not 500.\\\"\\\"\\\"\\n    body = {\\\"flow_id\\\": str(uuid4()), \\\"input_value\\\": \\\"In one short sentence, what is Langflow?\\\"}\\n    response = await client.post(\\\"api/v1/agentic/execute/LangflowAssistant\\\", json=body, headers=logged_in_headers)\\n    assert response.status_code != 500, response.text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_assistant_context_secretless_provider.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3d63a0243eb64d989e1cec407dc742a5087ed6fb026d44050fc8663a97cdd598\",\"content\":\"\\\"\\\"\\\"A provider that declares no secret must still resolve an assistant context.\\n\\nOllama configures itself with a base URL and no API key, so\\n``get_provider_secret_variable_key`` legitimately returns ``None`` for it.\\nTreating that ``None`` as an unrecognized provider made every assistant turn\\nfail with \\\"Unknown provider: Ollama\\\" while Settings still showed Ollama\\nconnected with its models listed.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import AsyncMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.agentic.api.router import _resolve_assistant_context\\nfrom langflow.agentic.api.schemas import AssistantRequest\\n\\n_ROUTER = \\\"langflow.agentic.api.router\\\"\\n\\n\\ndef _request(**overrides) -> AssistantRequest:\\n    payload = {\\\"flow_id\\\": str(uuid4()), \\\"input_value\\\": \\\"build me a flow\\\", **overrides}\\n    return AssistantRequest(**payload)\\n\\n\\n@pytest.fixture\\ndef _ollama_only_env():\\n    \\\"\\\"\\\"Ollama enabled and configured, with the real provider metadata in play.\\\"\\\"\\\"\\n    with (\\n        patch(\\n            f\\\"{_ROUTER}.get_enabled_providers_for_user\\\",\\n            new_callable=AsyncMock,\\n            return_value=([\\\"Ollama\\\"], {\\\"Ollama\\\": True}),\\n        ),\\n        patch(f\\\"{_ROUTER}.get_default_model\\\", return_value=\\\"llama3.2:latest\\\"),\\n        patch(\\n            f\\\"{_ROUTER}.get_all_variables_for_provider\\\",\\n            return_value={\\\"OLLAMA_BASE_URL\\\": \\\"http://localhost:11434\\\"},\\n        ),\\n    ):\\n        yield\\n\\n\\n@pytest.mark.usefixtures(\\\"_ollama_only_env\\\")\\nasync def test_explicit_ollama_provider_resolves_context():\\n    ctx = await _resolve_assistant_context(\\n        _request(provider=\\\"Ollama\\\", model_name=\\\"llama3.2:latest\\\"),\\n        uuid4(),\\n        session=AsyncMock(),\\n    )\\n\\n    assert ctx.provider == \\\"Ollama\\\"\\n    assert ctx.api_key_name is None\\n    assert ctx.global_vars[\\\"MODEL_NAME\\\"] == \\\"llama3.2:latest\\\"\\n    assert ctx.global_vars[\\\"OLLAMA_BASE_URL\\\"] == \\\"http://localhost:11434\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_ollama_only_env\\\")\\nasync def test_ollama_as_sole_provider_resolves_without_explicit_selection():\\n    \\\"\\\"\\\"No provider in the request: falling back to the only enabled one must work.\\\"\\\"\\\"\\n    ctx = await _resolve_assistant_context(_request(), uuid4(), session=AsyncMock())\\n\\n    assert ctx.provider == \\\"Ollama\\\"\\n    assert ctx.global_vars[\\\"PROVIDER\\\"] == \\\"Ollama\\\"\\n\\n\\nasync def test_genuinely_unknown_provider_is_still_rejected():\\n    \\\"\\\"\\\"The guard must keep rejecting a provider the model catalog does not know.\\n\\n    Pins the guard, not a reachable production path: enabled providers are built\\n    from the catalog, so anything that clears the enablement check above already\\n    satisfies recognition. Reaching this branch takes a mocked enablement result\\n    that enablement itself could never produce. Kept as defense in depth.\\n    \\\"\\\"\\\"\\n    with (\\n        patch(\\n            f\\\"{_ROUTER}.get_enabled_providers_for_user\\\",\\n            new_callable=AsyncMock,\\n            return_value=([\\\"NotAProvider\\\"], {\\\"NotAProvider\\\": True}),\\n        ),\\n        patch(f\\\"{_ROUTER}.get_default_model\\\", return_value=\\\"some-model\\\"),\\n        patch(f\\\"{_ROUTER}.get_all_variables_for_provider\\\", return_value={}),\\n        pytest.raises(HTTPException) as exc_info,\\n    ):\\n        await _resolve_assistant_context(\\n            _request(provider=\\\"NotAProvider\\\"),\\n            uuid4(),\\n            session=AsyncMock(),\\n        )\\n\\n    assert exc_info.value.status_code == 400\\n    assert \\\"Unknown provider\\\" in str(exc_info.value.detail)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_check_config_live_models.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dfc0dd0d1d287b82499652ac76a8a8de5e8fe465ad5510bfe4826b94a0e621a4\",\"content\":\"\\\"\\\"\\\"check-config must surface live installed models for live providers.\\n\\nReproduced live (2026-06-12, release-1.11.0, Ollama-only setup):\\n``GET /agentic/check-config`` returns the STATIC Ollama catalog (37\\nmodels headed by ``llama3.3``) while the running Ollama server has only\\n``gpt-oss:20b``, ``llama3.2:latest`` and ``qwen2.5:1.5b`` installed. The\\nfrontend picker and the backend default both point at models that 404.\\n\\nThe live fetch boundary (``get_live_models_for_provider``, reached via\\n``list_installed_tool_calling_models``) is mocked: it requires an\\nexternal Ollama server CI cannot reproduce.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import AsyncMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.agentic.api.router import check_assistant_config\\nfrom langflow.services.database.models.user.model import User\\n\\nROUTER_MODULE = \\\"langflow.agentic.api.router\\\"\\nPROVIDER_MODULE = \\\"langflow.agentic.services.provider_service\\\"\\n\\nINSTALLED_OLLAMA_MODELS = [\\n    {\\\"name\\\": \\\"gpt-oss:20b\\\", \\\"tool_calling\\\": True, \\\"model_type\\\": \\\"llm\\\"},\\n    {\\\"name\\\": \\\"llama3.2:latest\\\", \\\"tool_calling\\\": True, \\\"model_type\\\": \\\"llm\\\"},\\n    {\\\"name\\\": \\\"qwen2.5:1.5b\\\", \\\"tool_calling\\\": True, \\\"model_type\\\": \\\"llm\\\"},\\n]\\n\\n\\nclass TestCheckConfigLiveModels:\\n    @pytest.mark.asyncio\\n    async def test_should_list_installed_models_when_ollama_is_the_provider(self):\\n        user = User(id=uuid4(), username=\\\"tester\\\")\\n        with (\\n            patch(\\n                f\\\"{ROUTER_MODULE}.get_enabled_providers_for_user\\\",\\n                new_callable=AsyncMock,\\n                return_value=([\\\"Ollama\\\"], {\\\"Ollama\\\": True}),\\n            ),\\n            patch(\\n                f\\\"{PROVIDER_MODULE}.get_live_models_for_provider\\\",\\n                return_value=INSTALLED_OLLAMA_MODELS,\\n            ),\\n        ):\\n            config = await check_assistant_config(current_user=user, session=AsyncMock())\\n\\n        ollama = next(p for p in config[\\\"providers\\\"] if p[\\\"name\\\"] == \\\"Ollama\\\")\\n        model_names = [m[\\\"name\\\"] for m in ollama[\\\"models\\\"]]\\n        assert model_names == [\\\"gpt-oss:20b\\\", \\\"llama3.2:latest\\\", \\\"qwen2.5:1.5b\\\"], (\\n            f\\\"Expected the installed models, got the static catalog: {model_names[:5]}...\\\"\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_should_default_to_an_installed_model_not_the_catalog_default(self):\\n        user = User(id=uuid4(), username=\\\"tester\\\")\\n        with (\\n            patch(\\n                f\\\"{ROUTER_MODULE}.get_enabled_providers_for_user\\\",\\n                new_callable=AsyncMock,\\n                return_value=([\\\"Ollama\\\"], {\\\"Ollama\\\": True}),\\n            ),\\n            patch(\\n                f\\\"{PROVIDER_MODULE}.get_live_models_for_provider\\\",\\n                return_value=INSTALLED_OLLAMA_MODELS,\\n            ),\\n        ):\\n            config = await check_assistant_config(current_user=user, session=AsyncMock())\\n\\n        assert config[\\\"default_provider\\\"] == \\\"Ollama\\\"\\n        assert config[\\\"default_model\\\"] == \\\"gpt-oss:20b\\\", (\\n            f\\\"Default must be an installed model, got: {config['default_model']}\\\"\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_should_keep_static_catalog_when_live_fetch_returns_nothing(self):\\n        user = User(id=uuid4(), username=\\\"tester\\\")\\n        with (\\n            patch(\\n                f\\\"{ROUTER_MODULE}.get_enabled_providers_for_user\\\",\\n                new_callable=AsyncMock,\\n                return_value=([\\\"Ollama\\\"], {\\\"Ollama\\\": True}),\\n            ),\\n            patch(\\n                f\\\"{PROVIDER_MODULE}.get_live_models_for_provider\\\",\\n                return_value=[],\\n            ),\\n        ):\\n            config = await check_assistant_config(current_user=user, session=AsyncMock())\\n\\n        ollama = next(p for p in config[\\\"providers\\\"] if p[\\\"name\\\"] == \\\"Ollama\\\")\\n        assert ollama[\\\"models\\\"], \\\"Static catalog must remain as fallback when live fetch fails\\\"\\n        assert config[\\\"default_model\\\"] == \\\"llama3.3\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_code_extraction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d37da4ed05b7d24abb2dec5ec11544958c67d547e06350596c36db165f9e9524\",\"content\":\"\\\"\\\"\\\"Tests for code extraction from LLM responses.\\n\\nTests extract_python_code, helper functions (_find_code_blocks, _find_unclosed_code_block,\\n_find_component_code), validate_component_code, and the extract-validate integration flow.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.agentic.helpers.code_extraction import (\\n    _find_code_blocks,\\n    _find_component_code,\\n    _find_unclosed_code_block,\\n    extract_component_code,\\n    extract_python_code,\\n)\\nfrom langflow.agentic.helpers.validation import validate_component_code\\n\\nVALID_COMPONENT_CODE = \\\"\\\"\\\"from langflow.custom import Component\\nfrom langflow.io import MessageTextInput, Output\\nfrom langflow.schema.message import Message\\n\\n\\nclass HelloWorldComponent(Component):\\n    display_name = \\\"Hello World\\\"\\n    description = \\\"A simple hello world component.\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\"),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"process\\\"),\\n    ]\\n\\n    def process(self) -> Message:\\n        return Message(text=f\\\"Hello, {self.input_value}!\\\")\\n\\\"\\\"\\\"\\n\\nINCOMPLETE_COMPONENT_CODE = \\\"\\\"\\\"from langflow.custom import Component\\nfrom langflow.io import MessageTextInput, Output\\n\\n\\nclass IncompleteComponent(Component):\\n    display_name = \\\"Incomplete\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\"),\\n\\\"\\\"\\\"\\n\\nINVALID_SYNTAX_CODE = \\\"\\\"\\\"from langflow.custom import Component\\n\\nclass BrokenComponent(Component)\\n    display_name = \\\"Broken\\\"\\n\\\"\\\"\\\"\\n\\n\\nclass TestExtractPythonCode:\\n    \\\"\\\"\\\"Tests for extract_python_code function.\\\"\\\"\\\"\\n\\n    def test_extract_from_closed_python_block(self):\\n        \\\"\\\"\\\"Should extract code from a properly closed ```python block.\\\"\\\"\\\"\\n        text = f\\\"Here is the component:\\\\n\\\\n```python\\\\n{VALID_COMPONENT_CODE}\\\\n```\\\\n\\\\nLet me know if you need changes.\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"class HelloWorldComponent\\\" in result\\n        assert \\\"from langflow.custom import Component\\\" in result\\n\\n    def test_extract_from_unclosed_python_block(self):\\n        \\\"\\\"\\\"Should extract code from an unclosed ```python block.\\\"\\\"\\\"\\n        text = f\\\"Here is the component:\\\\n\\\\n```python\\\\n{VALID_COMPONENT_CODE}\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"class HelloWorldComponent\\\" in result\\n\\n    def test_extract_with_text_before_code(self):\\n        \\\"\\\"\\\"Should extract code even when there's text before the code block.\\\"\\\"\\\"\\n        text = f\\\"\\\"\\\"I apologize for the rate limit issue. Let me create a component.\\n\\nHere's a component that uses TextBlob for sentiment analysis:\\n\\n```python\\n{VALID_COMPONENT_CODE}\\n```\\\"\\\"\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"class HelloWorldComponent\\\" in result\\n\\n    def test_extract_from_unclosed_block_with_text_before(self):\\n        \\\"\\\"\\\"Should extract code from unclosed block even with text before it.\\\"\\\"\\\"\\n        text = f\\\"\\\"\\\"I apologize for the rate limit issue. Let me create the component.\\n\\n```python\\n{VALID_COMPONENT_CODE}\\\"\\\"\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"class HelloWorldComponent\\\" in result\\n        assert \\\"from langflow.custom import Component\\\" in result\\n\\n    def test_extract_from_generic_code_block(self):\\n        \\\"\\\"\\\"Should extract code from a generic ``` block without language specifier.\\\"\\\"\\\"\\n        text = f\\\"Here is the code:\\\\n\\\\n```\\\\n{VALID_COMPONENT_CODE}\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"class HelloWorldComponent\\\" in result\\n\\n    def test_returns_none_for_no_code_blocks(self):\\n        \\\"\\\"\\\"Should return None when there are no code blocks.\\\"\\\"\\\"\\n        text = \\\"This is just regular text without any code blocks.\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is None\\n\\n    def test_returns_none_for_empty_text(self):\\n        \\\"\\\"\\\"Should return None for empty text.\\\"\\\"\\\"\\n        result = extract_python_code(\\\"\\\")\\n\\n        assert result is None\\n\\n    def test_prefers_component_code_over_other_code(self):\\n        \\\"\\\"\\\"When multiple code blocks exist, should prefer the one with Component class.\\\"\\\"\\\"\\n        other_code = \\\"print('hello world')\\\"\\n        text = f\\\"\\\"\\\"Here's a simple print:\\n\\n```python\\n{other_code}\\n```\\n\\nAnd here's the component:\\n\\n```python\\n{VALID_COMPONENT_CODE}\\n```\\\"\\\"\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"class HelloWorldComponent\\\" in result\\n        assert result.strip() != other_code\\n\\n    def test_should_return_first_block_when_no_component_code(self):\\n        \\\"\\\"\\\"Should return first code block when none contain Component class.\\\"\\\"\\\"\\n        text = \\\"```python\\\\nprint('hello')\\\\n```\\\\n\\\\n```python\\\\nx = 42\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"print('hello')\\\" in result\\n\\n    def test_handles_code_with_special_characters(self):\\n        \\\"\\\"\\\"Should handle code containing special characters.\\\"\\\"\\\"\\n        code_with_specials = \\\"\\\"\\\"from langflow.custom import Component\\n\\nclass SpecialComponent(Component):\\n    display_name = \\\"Special < > & Characters\\\"\\n    description = \\\"Handles 'quotes' and \\\\\\\\\\\"escaped\\\\\\\\\\\" chars\\\"\\n\\\"\\\"\\\"\\n        text = f\\\"```python\\\\n{code_with_specials}\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"SpecialComponent\\\" in result\\n\\n\\nclass TestEdgeCases:\\n    \\\"\\\"\\\"Edge case tests for robustness.\\\"\\\"\\\"\\n\\n    def test_handles_windows_line_endings(self):\\n        \\\"\\\"\\\"Should handle Windows-style line endings (CRLF).\\\"\\\"\\\"\\n        code = VALID_COMPONENT_CODE.replace(\\\"\\\\n\\\", \\\"\\\\r\\\\n\\\")\\n        text = f\\\"```python\\\\r\\\\n{code}\\\\r\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"HelloWorldComponent\\\" in result\\n\\n    def test_handles_mixed_line_endings(self):\\n        \\\"\\\"\\\"Should handle mixed line endings.\\\"\\\"\\\"\\n        text = f\\\"Text\\\\r\\\\n```python\\\\n{VALID_COMPONENT_CODE}\\\\r\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n\\n    def test_handles_unicode_in_code(self):\\n        \\\"\\\"\\\"Should handle unicode characters in code.\\\"\\\"\\\"\\n        unicode_code = \\\"\\\"\\\"from langflow.custom import Component\\n\\nclass UnicodeComponent(Component):\\n    display_name = \\\"Unicode \\\\u00e9\\\\u00e0\\\\u00fc\\\"\\n    description = \\\"Handles \\\\u4e2d\\\\u6587 and \\\\ud83d\\\\ude00\\\"\\n\\\"\\\"\\\"\\n        text = f\\\"```python\\\\n{unicode_code}\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"Unicode\\\" in result\\n\\n    def test_handles_very_long_code(self):\\n        \\\"\\\"\\\"Should handle very long code blocks.\\\"\\\"\\\"\\n        long_code = VALID_COMPONENT_CODE + \\\"\\\\n\\\" * 1000 + \\\"# End of long code\\\"\\n        text = f\\\"```python\\\\n{long_code}\\\\n```\\\"\\n\\n        result = extract_python_code(text)\\n\\n        assert result is not None\\n        assert \\\"HelloWorldComponent\\\" in result\\n        assert \\\"End of long code\\\" in result\\n\\n    def test_case_insensitive_python_tag(self):\\n        \\\"\\\"\\\"Should handle Python tag with different cases.\\\"\\\"\\\"\\n        for tag in [\\\"```python\\\", \\\"```Python\\\", \\\"```PYTHON\\\", \\\"```PyThOn\\\"]:\\n            text = f\\\"{tag}\\\\n{VALID_COMPONENT_CODE}\\\\n```\\\"\\n\\n            result = extract_python_code(text)\\n\\n            assert result is not None, f\\\"Failed for tag: {tag}\\\"\\n\\n\\nclass TestFindCodeBlocks:\\n    \\\"\\\"\\\"Tests for _find_code_blocks helper function.\\\"\\\"\\\"\\n\\n    def test_finds_closed_python_blocks(self):\\n        \\\"\\\"\\\"Should find all closed python code blocks.\\\"\\\"\\\"\\n        text = \\\"```python\\\\ncode1\\\\n```\\\\n\\\\nText\\\\n\\\\n```python\\\\ncode2\\\\n```\\\"\\n\\n        result = _find_code_blocks(text)\\n\\n        assert len(result) == 2\\n        assert \\\"code1\\\" in result[0]\\n        assert \\\"code2\\\" in result[1]\\n\\n    def test_finds_unclosed_blocks_as_fallback(self):\\n        \\\"\\\"\\\"Should find unclosed blocks when no closed blocks exist.\\\"\\\"\\\"\\n        text = \\\"Some text\\\\n```python\\\\ncode_here\\\"\\n\\n        result = _find_code_blocks(text)\\n\\n        assert len(result) == 1\\n        assert \\\"code_here\\\" in result[0]\\n\\n\\nclass TestFindUnclosedCodeBlock:\\n    \\\"\\\"\\\"Tests for _find_unclosed_code_block helper function.\\\"\\\"\\\"\\n\\n    def test_finds_unclosed_python_block(self):\\n        \\\"\\\"\\\"Should find unclosed ```python block.\\\"\\\"\\\"\\n        text = \\\"Text before\\\\n```python\\\\ncode_content\\\"\\n\\n        result = _find_unclosed_code_block(text)\\n\\n        assert len(result) == 1\\n        assert \\\"code_content\\\" in result[0]\\n\\n    def test_finds_unclosed_generic_block(self):\\n        \\\"\\\"\\\"Should find unclosed ``` block without language.\\\"\\\"\\\"\\n        text = \\\"Text\\\\n```\\\\nsome code\\\"\\n\\n        result = _find_unclosed_code_block(text)\\n\\n        assert len(result) == 1\\n        assert \\\"some code\\\" in result[0]\\n\\n    def test_returns_empty_for_closed_blocks(self):\\n        \\\"\\\"\\\"Should return empty list when blocks are properly closed.\\\"\\\"\\\"\\n        text = \\\"```python\\\\ncode\\\\n```\\\"\\n\\n        result = _find_unclosed_code_block(text)\\n\\n        assert len(result) >= 0\\n\\n    def test_returns_empty_for_no_code_blocks(self):\\n        \\\"\\\"\\\"Should return empty list when no code blocks at all.\\\"\\\"\\\"\\n        text = \\\"Just regular text\\\"\\n\\n        result = _find_unclosed_code_block(text)\\n\\n        assert result == []\\n\\n    def test_handles_multiple_backticks_in_code(self):\\n        \\\"\\\"\\\"Should handle code that contains backticks.\\\"\\\"\\\"\\n        text = \\\"```python\\\\ncode with `inline` backticks\\\"\\n\\n        result = _find_unclosed_code_block(text)\\n\\n        assert len(result) == 1\\n        assert \\\"`inline`\\\" in result[0]\\n\\n\\nclass TestValidateComponentCode:\\n    \\\"\\\"\\\"Tests for validate_component_code function.\\\"\\\"\\\"\\n\\n    def test_validates_valid_component(self):\\n        \\\"\\\"\\\"Should validate correct Langflow component code.\\\"\\\"\\\"\\n        result = validate_component_code(VALID_COMPONENT_CODE)\\n\\n        assert result.is_valid is True\\n        assert result.class_name == \\\"HelloWorldComponent\\\"\\n        assert result.error is None\\n        assert result.code == VALID_COMPONENT_CODE\\n\\n    def test_fails_for_syntax_error(self):\\n        \\\"\\\"\\\"Should fail validation for code with syntax errors.\\\"\\\"\\\"\\n        result = validate_component_code(INVALID_SYNTAX_CODE)\\n\\n        assert result.is_valid is False\\n        assert result.error is not None\\n        assert \\\"expected\\\" in result.error.lower() or \\\"syntax\\\" in result.error.lower()\\n\\n    def test_fails_for_incomplete_code(self):\\n        \\\"\\\"\\\"Should fail validation for incomplete component code.\\\"\\\"\\\"\\n        result = validate_component_code(INCOMPLETE_COMPONENT_CODE)\\n\\n        assert result.is_valid is False\\n        assert result.error is not None\\n\\n    def test_fails_for_non_component_code(self):\\n        \\\"\\\"\\\"Should fail validation for code that's not a Langflow component.\\\"\\\"\\\"\\n        non_component_code = \\\"\\\"\\\"def hello():\\n    return \\\"hello\\\"\\n\\\"\\\"\\\"\\n        result = validate_component_code(non_component_code)\\n\\n        assert result.is_valid is False\\n        assert result.error is not None\\n\\n    def test_fails_for_empty_code(self):\\n        \\\"\\\"\\\"Should fail validation for empty string.\\\"\\\"\\\"\\n        result = validate_component_code(\\\"\\\")\\n\\n        assert result.is_valid is False\\n        assert result.error is not None\\n\\n    def test_passes_static_validation_without_imports(self):\\n        \\\"\\\"\\\"Static validation accepts syntactically valid code even without imports.\\n\\n        Import validation happens at runtime when the component is loaded into a flow,\\n        not during static analysis.\\n        \\\"\\\"\\\"\\n        code_without_imports = \\\"\\\"\\\"class BrokenComponent(Component):\\n    display_name = \\\"Broken\\\"\\n\\\"\\\"\\\"\\n        result = validate_component_code(code_without_imports)\\n\\n        assert result.is_valid is True\\n        assert result.class_name == \\\"BrokenComponent\\\"\\n\\n\\nclass TestCodeExtractionAndValidationIntegration:\\n    \\\"\\\"\\\"Integration tests for the full extract -> validate flow.\\\"\\\"\\\"\\n\\n    def test_full_flow_with_valid_response(self):\\n        \\\"\\\"\\\"Should extract and validate a complete valid response.\\\"\\\"\\\"\\n        llm_response = f\\\"\\\"\\\"I'll create a Hello World component for you.\\n\\n```python\\n{VALID_COMPONENT_CODE}\\n```\\n\\nThis component takes an input and returns a greeting message.\\\"\\\"\\\"\\n\\n        code = extract_python_code(llm_response)\\n        assert code is not None\\n\\n        validation = validate_component_code(code)\\n        assert validation.is_valid is True\\n        assert validation.class_name == \\\"HelloWorldComponent\\\"\\n\\n    def test_full_flow_with_unclosed_valid_response(self):\\n        \\\"\\\"\\\"Should extract and validate from unclosed but valid code.\\\"\\\"\\\"\\n        llm_response = f\\\"\\\"\\\"Here's your component:\\n\\n```python\\n{VALID_COMPONENT_CODE}\\\"\\\"\\\"\\n\\n        code = extract_python_code(llm_response)\\n        assert code is not None\\n\\n        validation = validate_component_code(code)\\n        assert validation.is_valid is True\\n\\n    def test_full_flow_with_invalid_code_returns_error(self):\\n        \\\"\\\"\\\"Should extract but fail validation for broken code.\\\"\\\"\\\"\\n        llm_response = f\\\"\\\"\\\"Here's the component:\\n\\n```python\\n{INVALID_SYNTAX_CODE}\\n```\\\"\\\"\\\"\\n\\n        code = extract_python_code(llm_response)\\n        assert code is not None\\n\\n        validation = validate_component_code(code)\\n        assert validation.is_valid is False\\n        assert validation.error is not None\\n        assert \\\"expected\\\" in validation.error.lower() or \\\"syntax\\\" in validation.error.lower()\\n\\n    def test_full_flow_with_text_heavy_response(self):\\n        \\\"\\\"\\\"Should handle responses with lots of explanatory text.\\\"\\\"\\\"\\n        llm_response = f\\\"\\\"\\\"I apologize for the previous rate limit error. Let me try again.\\n\\nBased on your request, I'll create a custom Langflow component that performs sentiment analysis.\\nThis component will:\\n1. Take text input\\n2. Process it through a sentiment analyzer\\n3. Return the sentiment score\\n\\nHere's the implementation:\\n\\n```python\\n{VALID_COMPONENT_CODE}\\n```\\n\\nTo use this component:\\n1. Drag it onto your canvas\\n2. Connect an input\\n3. The output will contain the sentiment analysis\\n\\nLet me know if you need any modifications!\\\"\\\"\\\"\\n\\n        code = extract_python_code(llm_response)\\n        assert code is not None\\n\\n        validation = validate_component_code(code)\\n        assert validation.is_valid is True\\n        assert validation.class_name == \\\"HelloWorldComponent\\\"\\n\\n\\nclass TestBugsAndEdgeCases:\\n    \\\"\\\"\\\"Tests that challenge the code \u2014 exposing real bugs and untested edge cases.\\\"\\\"\\\"\\n\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: extract_component_code overwritten by extract_python_code alias at L96\\\",\\n        strict=True,\\n    )\\n    def test_extract_component_code_should_reject_non_component(self):\\n        \\\"\\\"\\\"extract_component_code should return None for non-component code.\\\"\\\"\\\"\\n        result = extract_component_code(\\\"```python\\\\nx = 1\\\\n```\\\")\\n        assert result is None\\n\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: empty code block returns '' instead of None (L60 matches[0].strip())\\\",\\n        strict=True,\\n    )\\n    def test_should_return_none_for_empty_code_block(self):\\n        \\\"\\\"\\\"extract_python_code should return None for empty code blocks.\\\"\\\"\\\"\\n        result = extract_python_code(\\\"```python\\\\n\\\\n```\\\")\\n        assert result is None\\n\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: rstrip('`') at L81 strips ALL trailing backticks, corrupting code\\\",\\n        strict=True,\\n    )\\n    def test_rstrip_should_not_corrupt_code_with_backticks(self):\\n        \\\"\\\"\\\"Unclosed blocks should not strip backticks that are part of the code.\\\"\\\"\\\"\\n        text = '```python\\\\nmarkdown_var = \\\"```\\\"'\\n        result = extract_python_code(text)\\n        assert result is not None\\n        assert '```\\\"' in result\\n\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: L90 'Component' in match matches ComponentFactory, not just inheritance\\\",\\n        strict=True,\\n    )\\n    def test_find_component_code_false_positive_substring(self):\\n        \\\"\\\"\\\"_find_component_code should not match non-Component classes.\\\"\\\"\\\"\\n        non_component = \\\"class ComponentFactory:\\\\n    pass\\\"\\n        result = _find_component_code([non_component])\\n        assert result is None\\n\\n    def test_nested_code_blocks_truncate_content(self):\\n        \\\"\\\"\\\"Non-greedy regex truncates code with embedded triple backticks.\\\"\\\"\\\"\\n        text = '```python\\\\ncode = \\\"\\\"\\\"Example:\\\\n```python\\\\ninner\\\\n```\\\\n\\\"\\\"\\\"\\\\n```'\\n        result = extract_python_code(text)\\n        assert result is not None\\n        # Documents: non-greedy regex stops at first ```, truncating inner content\\n        assert \\\"inner\\\" not in result\\n\\n    def test_extract_python_code_whitespace_only_block(self):\\n        \\\"\\\"\\\"Whitespace-only code block should be falsy.\\\"\\\"\\\"\\n        result = extract_python_code(\\\"```python\\\\n   \\\\n```\\\")\\n        assert not result\\n\\n    def test_generic_pattern_ignores_language_tags(self):\\n        r\\\"\\\"\\\"Generic code block pattern expects whitespace after ```, not a language tag.\\n\\n        ```CODE\\\\\\\\n and ```code\\\\\\\\n both fail to match ```\\\\\\\\s*\\\\\\\\n because\\n        'CODE'/'code' are not whitespace. Only ```\\\\\\\\n or ``` \\\\\\\\n match.\\n        \\\"\\\"\\\"\\n        text_with_tag = \\\"```CODE\\\\nprint('hello')\\\\n```\\\"\\n        text_without_tag = \\\"```\\\\nprint('hello')\\\\n```\\\"\\n        result_with_tag = _find_code_blocks(text_with_tag)\\n        result_without_tag = _find_code_blocks(text_without_tag)\\n        # Only the tagless version matches the generic pattern\\n        assert len(result_without_tag) >= len(result_with_tag)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_files_endpoint.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7cd808dd65dfbe19b16e88bc0808bea8b03f66fe419bd1cb55d3c42da1c14f36\",\"content\":\"\\\"\\\"\\\"Security tests for the agentic files endpoint.\\n\\nThe endpoint lets the frontend read files the agent wrote inside the\\nsandboxed workspace. Every adversarial test below maps to one threat in\\n``CZL/DEVELOPMENT/PLAN_document_assistant.md`` (T1-T13).\\n\\nTests invoke the route handler directly (not via TestClient) so we focus on\\nthe security logic - authentication is decoupled via a mock ``current_user``.\\nEnd-to-end HTTP wiring is covered by the integration smoke test at the end.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom fastapi.responses import Response\\nfrom langflow.agentic.api.files_router import get_file\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _make_user(user_id: str = \\\"u-abc\\\") -> SimpleNamespace:\\n    return SimpleNamespace(id=user_id)\\n\\n\\ndef _write_sandbox_file(sandbox_root: Path, user_id: str, relative_path: str, content: bytes) -> Path:  # noqa: ARG001\\n    \\\"\\\"\\\"Materialize a file inside the user's FileSystemToolComponent sandbox.\\n\\n    Reproduces the layout FileSystemToolComponent uses so the endpoint\\n    resolves the same way as the agent's write_file tool. AUTO_LOGIN=False\\n    path: ``<base>/<namespace>/<relative>``. The namespace is derived from\\n    user_id + pepper inside FileSystemToolComponent \u2014 we just write into the\\n    namespace it computes so we can later read it back.\\n    \\\"\\\"\\\"\\n    # Force the FileSystemToolComponent to be the single source of truth for\\n    # path layout \u2014 instantiate it, validate the root, then write our fixture\\n    # into the same directory.\\n    from lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n    fs = FileSystemToolComponent()\\n    fs._user_id = user_id\\n    root = fs._validate_root()\\n    target = root / relative_path\\n    target.parent.mkdir(parents=True, exist_ok=True)\\n    target.write_bytes(content)\\n    return target\\n\\n\\n@pytest.fixture\\ndef isolated_sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    \\\"\\\"\\\"Point the FS tool sandbox at a fresh tmp_path with AUTO_LOGIN disabled.\\n\\n    Why not ``monkeypatch.setenv(\\\"LANGFLOW_AUTO_LOGIN\\\", \\\"false\\\")``: the settings\\n    service is a process-wide singleton that caches ``AUTO_LOGIN`` on first\\n    access. The env var revert at test teardown doesn't un-cache the value,\\n    so subsequent tests in the suite (e.g., the flow_builder filesystem-tool\\n    tests) would inherit ``AUTO_LOGIN=False`` and fail because they don't\\n    bind a user_id. We pin the per-instance method instead \u2014 no global state.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    from lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n    monkeypatch.setattr(\\n        FileSystemToolComponent,\\n        \\\"_resolve_auto_login\\\",\\n        lambda self: False,  # noqa: ARG005\\n    )\\n    return tmp_path\\n\\n\\nclass TestHappyPath:\\n    \\\"\\\"\\\"B5 happy path \u2014 authenticated user reads a file in their own sandbox.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_file_content_when_path_valid(self, isolated_sandbox):\\n        # Arrange \u2014 materialize a file in user u-abc's namespace.\\n        user = _make_user(\\\"u-abc\\\")\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"DOCS.md\\\", b\\\"# Title\\\\n\\\\nHello.\\\")\\n\\n        # Act\\n        response = await get_file(path=\\\"DOCS.md\\\", download=False, current_user=user)\\n\\n        # Assert\\n        assert isinstance(response, Response)\\n        assert response.status_code == 200\\n        assert response.body == b\\\"# Title\\\\n\\\\nHello.\\\"\\n        assert response.media_type.startswith(\\\"text/plain\\\")\\n\\n\\nclass TestPathTraversalRejection:\\n    \\\"\\\"\\\"B5 \u2014 T1: path traversal must be refused BEFORE any I/O is attempted.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.parametrize(\\n        \\\"evil_path\\\",\\n        [\\n            \\\"../escape.md\\\",\\n            \\\"../../etc/passwd\\\",\\n            \\\"subdir/../../../escape.md\\\",\\n            \\\"subdir/..\\\",\\n        ],\\n    )\\n    async def test_should_reject_path_when_contains_dotdot(self, isolated_sandbox, evil_path):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=evil_path, download=False, current_user=user)\\n        assert exc.value.status_code == 400\\n\\n    @pytest.mark.asyncio\\n    async def test_should_reject_path_when_absolute_unix(self, isolated_sandbox):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"/etc/passwd\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 400\\n\\n    @pytest.mark.asyncio\\n    async def test_should_reject_path_when_absolute_unix_backslash(self, isolated_sandbox):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"\\\\\\\\etc\\\\\\\\passwd\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 400\\n\\n    @pytest.mark.asyncio\\n    async def test_should_reject_path_when_windows_drive_letter(self, isolated_sandbox):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"C:\\\\\\\\Users\\\\\\\\victim\\\\\\\\file.md\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 400\\n\\n    @pytest.mark.asyncio\\n    async def test_should_reject_path_when_null_byte(self, isolated_sandbox):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"DOCS.md\\\\x00.txt\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 400\\n\\n    @pytest.mark.asyncio\\n    async def test_should_reject_path_when_empty(self, isolated_sandbox):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"\\\", download=False, current_user=user)\\n        # Either 400 from our pre-validation or 422 from FastAPI \u2014 both are\\n        # acceptable refusals; we just don't tolerate a 200.\\n        assert exc.value.status_code in {400, 422}\\n\\n\\nclass TestCrossUserDenial:\\n    \\\"\\\"\\\"B5 \u2014 T2: user B must not read user A's files. Returns 404 (not 403)\\n    so the existence of A's namespace is not leaked.\\n    \\\"\\\"\\\"  # noqa: D205\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_404_when_target_in_other_user_namespace(self, isolated_sandbox):\\n        # Arrange \u2014 write a file as user A.\\n        _write_sandbox_file(isolated_sandbox, \\\"user-a\\\", \\\"SECRET.md\\\", b\\\"a's secret\\\")\\n\\n        # Act \u2014 user B requests the SAME relative path (a's namespace has it,\\n        # b's namespace doesn't). The endpoint resolves under b's namespace,\\n        # finds nothing.\\n        user_b = _make_user(\\\"user-b\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"SECRET.md\\\", download=False, current_user=user_b)\\n\\n        # 404 \u2014 not 403 \u2014 so we don't leak the existence of A's namespace.\\n        assert exc.value.status_code == 404\\n\\n\\nclass TestMissingFile:\\n    \\\"\\\"\\\"B5 \u2014 request for a file that doesn't exist returns 404.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_404_when_file_does_not_exist(self, isolated_sandbox):  # noqa: ARG002\\n        user = _make_user(\\\"u-abc\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"NONEXISTENT.md\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 404\\n\\n\\nclass TestSizeAndBinaryGuards:\\n    \\\"\\\"\\\"B5 \u2014 T8 (oversize), T9 (binary): refused with the right status code.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_413_when_file_exceeds_max_size(self, isolated_sandbox, monkeypatch):\\n        from lfx.components.tools import filesystem as fs_module\\n\\n        # Reduce the cap so we can exercise the limit cheaply.\\n        monkeypatch.setattr(fs_module, \\\"MAX_FILE_SIZE_BYTES\\\", 16)\\n\\n        user = _make_user(\\\"u-abc\\\")\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"BIG.md\\\", b\\\"x\\\" * 32)\\n\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"BIG.md\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 413\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_415_when_file_is_binary(self, isolated_sandbox):\\n        user = _make_user(\\\"u-abc\\\")\\n        # A null byte in the first 8 KiB marks the file as binary per\\n        # FileSystemToolComponent's heuristic.\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"BIN.dat\\\", b\\\"\\\\x00\\\\x01\\\\x02hello\\\")\\n\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"BIN.dat\\\", download=False, current_user=user)\\n        assert exc.value.status_code == 415\\n\\n\\nclass TestDownloadMode:\\n    \\\"\\\"\\\"B5 \u2014 T7: ?download=true must force attachment + octet-stream so the\\n    browser never inlines a returned .html / .svg / .js as page content.\\n    \\\"\\\"\\\"  # noqa: D205\\n\\n    @pytest.mark.asyncio\\n    async def test_should_set_content_disposition_attachment_when_download_true(self, isolated_sandbox):\\n        user = _make_user(\\\"u-abc\\\")\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"DOCS.md\\\", b\\\"hello\\\")\\n\\n        response = await get_file(path=\\\"DOCS.md\\\", download=True, current_user=user)\\n\\n        assert response.status_code == 200\\n        cd = response.headers.get(\\\"content-disposition\\\", \\\"\\\")\\n        assert cd.startswith(\\\"attachment;\\\"), cd\\n        assert \\\"DOCS.md\\\" in cd\\n\\n    @pytest.mark.asyncio\\n    async def test_should_force_octet_stream_when_download_true(self, isolated_sandbox):\\n        user = _make_user(\\\"u-abc\\\")\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"DOCS.md\\\", b\\\"hello\\\")\\n\\n        response = await get_file(path=\\\"DOCS.md\\\", download=True, current_user=user)\\n        assert response.media_type == \\\"application/octet-stream\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_sanitize_filename_in_content_disposition(self, isolated_sandbox):\\n        \\\"\\\"\\\"A quote in the filename must not break out of the header value.\\\"\\\"\\\"\\n        user = _make_user(\\\"u-abc\\\")\\n        # Most filesystems allow quotes; we still want our header builder to\\n        # be robust if the LLM (or a future contributor) names a file weirdly.\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"weird.md\\\", b\\\"x\\\")\\n\\n        response = await get_file(path=\\\"weird.md\\\", download=True, current_user=user)\\n        cd = response.headers.get(\\\"content-disposition\\\", \\\"\\\")\\n        # Header is well-formed: exactly one filename=\\\"...\\\" segment.\\n        assert cd.count('filename=\\\"') == 1\\n\\n\\nclass TestAuditLogging:\\n    \\\"\\\"\\\"B5 \u2014 T11: every successful read emits an audit log line with the\\n    user_id, the (relative) path, and the size.\\n    \\\"\\\"\\\"  # noqa: D205\\n\\n    @pytest.mark.asyncio\\n    async def test_should_log_audit_event_when_file_read(self, isolated_sandbox, caplog):\\n        user = _make_user(\\\"u-abc\\\")\\n        _write_sandbox_file(isolated_sandbox, \\\"u-abc\\\", \\\"DOCS.md\\\", b\\\"hi\\\")\\n\\n        with caplog.at_level(\\\"INFO\\\"):\\n            await get_file(path=\\\"DOCS.md\\\", download=False, current_user=user)\\n\\n        records = [r for r in caplog.records if \\\"agentic.files.read\\\" in r.message]\\n        assert records, f\\\"Expected an agentic.files.read log entry, got: {[r.message for r in caplog.records]}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_files_endpoint_force_isolation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66e1d9a8d1608adb66ae6d0d7ad1462578fe94e05863c319eca830d40edb414c\",\"content\":\"\\\"\\\"\\\"B1 \u2014 /agentic/files must isolate users even under AUTO_LOGIN=True.\\n\\nThe existing endpoint suite pins AUTO_LOGIN=False globally; this file\\ncovers the missing AUTO_LOGIN=True branch (the platform default) and\\nproves the cross-user IDOR documented in the review is closed.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.agentic.api.files_router import get_file\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _make_user(user_id: str) -> SimpleNamespace:\\n    return SimpleNamespace(id=user_id)\\n\\n\\n@pytest.fixture\\ndef auto_login_sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    \\\"\\\"\\\"Pin AUTO_LOGIN=True per-instance + point at a fresh tmp_path.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    from lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n    monkeypatch.setattr(\\n        FileSystemToolComponent,\\n        \\\"_resolve_auto_login\\\",\\n        lambda self: True,  # noqa: ARG005\\n    )\\n    return tmp_path\\n\\n\\ndef _simulate_agent_write(user_id: str, relative: str, content: bytes) -> None:\\n    \\\"\\\"\\\"Write the way the agent's write tools will after B1 wiring.\\n\\n    force_isolation=True + bound user_id, so the file lands in users/<hash>/.\\n    \\\"\\\"\\\"\\n    from lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n    fs = FileSystemToolComponent()\\n    fs._user_id = user_id\\n    fs._force_isolation = True\\n    root = fs._validate_root()\\n    target = root / relative\\n    target.parent.mkdir(parents=True, exist_ok=True)\\n    target.write_bytes(content)\\n\\n\\nclass TestEndpointIsolatesUsersUnderAutoLogin:\\n    @pytest.mark.asyncio\\n    async def test_should_return_404_when_user_b_requests_user_a_file(self, auto_login_sandbox):  # noqa: ARG002\\n        # Arrange \u2014 Alice owns the file (agent-simulated write).\\n        _simulate_agent_write(\\\"user-alice\\\", \\\"secret.md\\\", b\\\"alice-owned\\\")\\n\\n        # Act \u2014 Bob asks the endpoint for the same path.\\n        bob = _make_user(\\\"user-bob\\\")\\n        with pytest.raises(HTTPException) as exc:\\n            await get_file(path=\\\"secret.md\\\", download=False, current_user=bob)\\n\\n        # Assert \u2014 the endpoint must NOT serve another user's file. 404 (not\\n        # 403) keeps namespace existence opaque, matching the existing policy.\\n        assert exc.value.status_code == 404\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_file_when_owner_requests_own_file(self, auto_login_sandbox):  # noqa: ARG002\\n        _simulate_agent_write(\\\"user-alice\\\", \\\"notes.md\\\", b\\\"# Alice notes\\\\n\\\")\\n\\n        alice = _make_user(\\\"user-alice\\\")\\n        response = await get_file(path=\\\"notes.md\\\", download=False, current_user=alice)\\n\\n        assert response.status_code == 200\\n        assert response.body == b\\\"# Alice notes\\\\n\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_iterations_limit_forwarding.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c21cb9f923e4603115e885b8f26157fd1b32ecd512979211743a3dcf7f8ebbc\",\"content\":\"\\\"\\\"\\\"The request's ``iterations_limit`` must reach every assistant endpoint.\\n\\nPR #14094 review finding: ``AssistantRequest`` accepts ``iterations_limit``\\nbut only ``/assist/stream`` forwarded it \u2014 ``/assist`` and\\n``/execute/{flow_name}`` silently executed with the default budget. The fix\\nseeds ``ITERATIONS_LIMIT`` centrally in ``_resolve_assistant_context`` so any\\nendpoint consuming ``ctx.global_vars`` honors the cap.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import AsyncMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.agentic.api.router import _resolve_assistant_context\\nfrom langflow.agentic.api.schemas import AssistantRequest\\n\\n_ROUTER = \\\"langflow.agentic.api.router\\\"\\n\\n\\ndef _request(**overrides) -> AssistantRequest:\\n    payload = {\\\"flow_id\\\": str(uuid4()), \\\"input_value\\\": \\\"build me a flow\\\", **overrides}\\n    return AssistantRequest(**payload)\\n\\n\\n@pytest.fixture\\ndef _provider_env():\\n    with (\\n        patch(\\n            f\\\"{_ROUTER}.get_enabled_providers_for_user\\\",\\n            new_callable=AsyncMock,\\n            return_value=([\\\"OpenAI\\\"], {}),\\n        ),\\n        patch(\\n            f\\\"{_ROUTER}.get_provider_secret_variable_key\\\",\\n            return_value=\\\"OPENAI_API_KEY\\\",\\n        ),\\n        patch(f\\\"{_ROUTER}.get_default_model\\\", return_value=\\\"gpt-4o\\\"),\\n        patch(\\n            f\\\"{_ROUTER}.get_all_variables_for_provider\\\",\\n            return_value={\\\"OPENAI_API_KEY\\\": \\\"sk-test\\\"},\\n        ),\\n        patch(\\n            f\\\"{_ROUTER}.get_provider_required_variable_keys\\\",\\n            return_value=[\\\"OPENAI_API_KEY\\\"],\\n        ),\\n    ):\\n        yield\\n\\n\\n@pytest.mark.usefixtures(\\\"_provider_env\\\")\\nasync def test_iterations_limit_is_seeded_into_global_vars():\\n    \\\"\\\"\\\"Central seeding covers /assist, /assist/stream, and /execute/{flow_name} at once.\\\"\\\"\\\"\\n    session = AsyncMock()\\n    ctx = await _resolve_assistant_context(_request(iterations_limit=1), uuid4(), session=session)\\n\\n    assert ctx.global_vars[\\\"ITERATIONS_LIMIT\\\"] == \\\"1\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_provider_env\\\")\\nasync def test_absent_iterations_limit_leaves_global_vars_unbudgeted():\\n    session = AsyncMock()\\n    ctx = await _resolve_assistant_context(_request(), uuid4(), session=session)\\n\\n    assert \\\"ITERATIONS_LIMIT\\\" not in ctx.global_vars\\n\\n\\nasync def test_credentialless_extension_provider_resolves_without_api_key_name():\\n    with (\\n        patch(\\n            f\\\"{_ROUTER}.get_enabled_providers_for_user\\\",\\n            new_callable=AsyncMock,\\n            return_value=([\\\"AmbientAuthCo\\\"], {\\\"AmbientAuthCo\\\": True}),\\n        ),\\n        patch(f\\\"{_ROUTER}.get_provider_secret_variable_key\\\", return_value=None),\\n        patch(f\\\"{_ROUTER}.is_known_model_provider\\\", return_value=True),\\n        patch(f\\\"{_ROUTER}.get_default_model\\\", return_value=\\\"ambient-chat\\\"),\\n        patch(f\\\"{_ROUTER}.get_all_variables_for_provider\\\", return_value={}),\\n        patch(f\\\"{_ROUTER}.get_provider_required_variable_keys\\\", return_value=[]),\\n    ):\\n        ctx = await _resolve_assistant_context(\\n            _request(provider=\\\"AmbientAuthCo\\\"),\\n            uuid4(),\\n            session=AsyncMock(),\\n        )\\n\\n    assert ctx.provider == \\\"AmbientAuthCo\\\"\\n    assert ctx.api_key_name is None\\n    assert ctx.global_vars[\\\"MODEL_NAME\\\"] == \\\"ambient-chat\\\"\\n\\n\\nasync def test_base_url_only_provider_does_not_inject_connection_config_as_api_key():\\n    with (\\n        patch(\\n            f\\\"{_ROUTER}.get_enabled_providers_for_user\\\",\\n            new_callable=AsyncMock,\\n            return_value=([\\\"LocalCo\\\"], {\\\"LocalCo\\\": True}),\\n        ),\\n        patch(f\\\"{_ROUTER}.get_provider_secret_variable_key\\\", return_value=None),\\n        patch(f\\\"{_ROUTER}.is_known_model_provider\\\", return_value=True),\\n        patch(f\\\"{_ROUTER}.get_default_model\\\", return_value=\\\"local-chat\\\"),\\n        patch(f\\\"{_ROUTER}.get_all_variables_for_provider\\\", return_value={\\\"LOCALCO_BASE_URL\\\": \\\"http://local\\\"}),\\n        patch(f\\\"{_ROUTER}.get_provider_required_variable_keys\\\", return_value=[\\\"LOCALCO_BASE_URL\\\"]),\\n    ):\\n        ctx = await _resolve_assistant_context(\\n            _request(provider=\\\"LocalCo\\\"),\\n            uuid4(),\\n            session=AsyncMock(),\\n        )\\n\\n    assert ctx.api_key_name is None\\n    assert ctx.global_vars[\\\"LOCALCO_BASE_URL\\\"] == \\\"http://local\\\"\\n\\n\\nasync def test_non_streaming_execution_binds_the_iterations_context():\\n    \\\"\\\"\\\"The nested generate_component subflow reads the budget from the run context.\\n\\n    ``execute_flow_with_validation`` (the /assist non-streaming path) must bind\\n    the ContextVar while the flow runs, and clear it afterwards.\\n    \\\"\\\"\\\"\\n    from langflow.agentic.services import assistant_service\\n    from langflow.agentic.services.agent_run_context import current_agent_run_iterations\\n\\n    captured: dict[str, int | None] = {}\\n\\n    async def fake_execute_flow_file(**_kwargs) -> dict:\\n        captured[\\\"limit\\\"] = current_agent_run_iterations()\\n        return {\\\"result\\\": \\\"ok\\\"}\\n\\n    with patch.object(assistant_service, \\\"execute_flow_file\\\", side_effect=fake_execute_flow_file):\\n        await assistant_service.execute_flow_with_validation(\\n            flow_filename=\\\"LangflowAssistant.json\\\",\\n            input_value=\\\"hello\\\",\\n            global_variables={\\\"ITERATIONS_LIMIT\\\": \\\"2\\\"},\\n        )\\n\\n    assert captured[\\\"limit\\\"] == 2\\n    assert current_agent_run_iterations() is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_openapi_visibility.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d804cc8760024da3e8edf66c9429b433e7ffb03309291e47edc0723aeb5181e0\",\"content\":\"\\\"\\\"\\\"Agentic routers must stay hidden from /openapi.json.\\n\\nThe assistant and files HTTP surfaces are internal. They are mounted with\\n``include_in_schema=False`` so they do not appear in the published OpenAPI\\nspec, Swagger UI, or generated SDKs.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\nfrom langflow.agentic.api.files_router import router as files_router\\nfrom langflow.agentic.api.router import router as assistant_router\\n\\nHIDDEN_AGENTIC_PATHS = (\\n    \\\"/agentic/assist\\\",\\n    \\\"/agentic/assist/stream\\\",\\n    \\\"/agentic/check-config\\\",\\n    \\\"/agentic/files\\\",\\n    \\\"/agentic/execute/{flow_name}\\\",\\n)\\n\\n\\ndef _build_schema() -> dict:\\n    \\\"\\\"\\\"Mount the two agentic routers on a clean FastAPI app and return its OpenAPI schema.\\\"\\\"\\\"\\n    app = FastAPI()\\n    app.include_router(assistant_router)\\n    app.include_router(files_router)\\n    client = TestClient(app)\\n    response = client.get(\\\"/openapi.json\\\")\\n    assert response.status_code == 200\\n    return response.json()\\n\\n\\nclass TestAgenticRoutersHiddenFromOpenApi:\\n    \\\"\\\"\\\"Agentic endpoints are internal and must not appear in the OpenAPI schema.\\\"\\\"\\\"\\n\\n    def test_should_hide_assist_endpoint(self):\\n        paths = _build_schema().get(\\\"paths\\\", {})\\n        assert \\\"/agentic/assist\\\" not in paths, f\\\"Expected /agentic/assist to be hidden, got paths: {sorted(paths)}\\\"\\n\\n    def test_should_hide_assist_stream_endpoint(self):\\n        paths = _build_schema().get(\\\"paths\\\", {})\\n        assert \\\"/agentic/assist/stream\\\" not in paths, (\\n            f\\\"Expected /agentic/assist/stream to be hidden, got paths: {sorted(paths)}\\\"\\n        )\\n\\n    def test_should_hide_check_config_endpoint(self):\\n        paths = _build_schema().get(\\\"paths\\\", {})\\n        assert \\\"/agentic/check-config\\\" not in paths, (\\n            f\\\"Expected /agentic/check-config to be hidden, got paths: {sorted(paths)}\\\"\\n        )\\n\\n    def test_should_hide_files_endpoint(self):\\n        paths = _build_schema().get(\\\"paths\\\", {})\\n        assert \\\"/agentic/files\\\" not in paths, f\\\"Expected /agentic/files to be hidden, got paths: {sorted(paths)}\\\"\\n\\n    def test_should_hide_execute_endpoint(self):\\n        paths = _build_schema().get(\\\"paths\\\", {})\\n        assert \\\"/agentic/execute/{flow_name}\\\" not in paths, (\\n            f\\\"Expected /agentic/execute/{{flow_name}} to be hidden, got paths: {sorted(paths)}\\\"\\n        )\\n\\n    def test_schema_contains_no_agentic_paths(self):\\n        paths = _build_schema().get(\\\"paths\\\", {})\\n        leaked = [path for path in HIDDEN_AGENTIC_PATHS if path in paths]\\n        assert leaked == [], f\\\"Agentic endpoints leaked into OpenAPI: {leaked}\\\"\\n        assert paths == {}, f\\\"Agentic routers must be hidden from OpenAPI, got paths: {sorted(paths)}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9f34958552a713d9f22b98f096c7e7aa93a862c177209d69d41784d90390b79e\",\"content\":\"\\\"\\\"\\\"Tests for API schemas.\\n\\nTests the Pydantic models used for request/response validation.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.agentic.api.schemas import (\\n    AssistantRequest,\\n    HeadlessAssistantRequest,\\n    StepType,\\n    ValidationResult,\\n)\\nfrom lfx.services.deps import get_settings_service\\nfrom pydantic import ValidationError\\n\\n\\nclass TestAssistantRequest:\\n    \\\"\\\"\\\"Tests for AssistantRequest schema.\\\"\\\"\\\"\\n\\n    def test_should_create_with_required_field_only(self):\\n        \\\"\\\"\\\"Should create request with only required flow_id field.\\\"\\\"\\\"\\n        request = AssistantRequest(flow_id=\\\"test-flow-id\\\")\\n\\n        assert request.flow_id == \\\"test-flow-id\\\"\\n        assert request.component_id is None\\n        assert request.field_name is None\\n        assert request.input_value is None\\n        assert request.max_retries is None\\n        assert request.model_name is None\\n        assert request.provider is None\\n        assert request.session_id is None\\n\\n    def test_should_create_with_all_fields(self):\\n        \\\"\\\"\\\"Should create request with all fields populated.\\\"\\\"\\\"\\n        request = AssistantRequest(\\n            flow_id=\\\"flow-123\\\",\\n            component_id=\\\"comp-456\\\",\\n            field_name=\\\"input_field\\\",\\n            input_value=\\\"Hello, world!\\\",\\n            max_retries=5,\\n            model_name=\\\"gpt-4\\\",\\n            provider=\\\"OpenAI\\\",\\n            session_id=\\\"session-789\\\",\\n        )\\n\\n        assert request.flow_id == \\\"flow-123\\\"\\n        assert request.component_id == \\\"comp-456\\\"\\n        assert request.field_name == \\\"input_field\\\"\\n        assert request.input_value == \\\"Hello, world!\\\"\\n        assert request.max_retries == 5\\n        assert request.model_name == \\\"gpt-4\\\"\\n        assert request.provider == \\\"OpenAI\\\"\\n        assert request.session_id == \\\"session-789\\\"\\n\\n    def test_should_raise_error_for_missing_flow_id(self):\\n        \\\"\\\"\\\"Should raise validation error when flow_id is missing.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError) as exc_info:\\n            AssistantRequest()\\n\\n        assert \\\"flow_id\\\" in str(exc_info.value)\\n\\n    def test_should_accept_empty_string_for_optional_fields(self):\\n        \\\"\\\"\\\"Should accept empty string for optional string fields.\\\"\\\"\\\"\\n        request = AssistantRequest(\\n            flow_id=\\\"test\\\",\\n            input_value=\\\"\\\",\\n            component_id=\\\"\\\",\\n        )\\n\\n        assert request.input_value == \\\"\\\"\\n        assert request.component_id == \\\"\\\"\\n\\n    def test_should_serialize_to_dict(self):\\n        \\\"\\\"\\\"Should serialize to dictionary correctly.\\\"\\\"\\\"\\n        request = AssistantRequest(\\n            flow_id=\\\"test-flow\\\",\\n            max_retries=3,\\n            provider=\\\"Anthropic\\\",\\n        )\\n\\n        data = request.model_dump()\\n\\n        assert data[\\\"flow_id\\\"] == \\\"test-flow\\\"\\n        assert data[\\\"max_retries\\\"] == 3\\n        assert data[\\\"provider\\\"] == \\\"Anthropic\\\"\\n        assert data[\\\"component_id\\\"] is None\\n\\n    def test_should_deserialize_from_dict(self):\\n        \\\"\\\"\\\"Should deserialize from dictionary correctly.\\\"\\\"\\\"\\n        data = {\\n            \\\"flow_id\\\": \\\"test-flow\\\",\\n            \\\"input_value\\\": \\\"test input\\\",\\n            \\\"max_retries\\\": 2,\\n        }\\n\\n        request = AssistantRequest(**data)\\n\\n        assert request.flow_id == \\\"test-flow\\\"\\n        assert request.input_value == \\\"test input\\\"\\n        assert request.max_retries == 2\\n\\n\\nclass TestValidationResult:\\n    \\\"\\\"\\\"Tests for ValidationResult schema.\\\"\\\"\\\"\\n\\n    def test_should_create_valid_result(self):\\n        \\\"\\\"\\\"Should create a valid validation result.\\\"\\\"\\\"\\n        result = ValidationResult(\\n            is_valid=True,\\n            code=\\\"class MyComponent(Component): pass\\\",\\n            class_name=\\\"MyComponent\\\",\\n        )\\n\\n        assert result.is_valid is True\\n        assert result.code == \\\"class MyComponent(Component): pass\\\"\\n        assert result.class_name == \\\"MyComponent\\\"\\n        assert result.error is None\\n\\n    def test_should_create_invalid_result_with_error(self):\\n        \\\"\\\"\\\"Should create an invalid validation result with error.\\\"\\\"\\\"\\n        result = ValidationResult(\\n            is_valid=False,\\n            code=\\\"class Broken(Component)\\\",\\n            error=\\\"SyntaxError: expected ':'\\\",\\n            class_name=\\\"Broken\\\",\\n        )\\n\\n        assert result.is_valid is False\\n        assert result.error == \\\"SyntaxError: expected ':'\\\"\\n        assert result.class_name == \\\"Broken\\\"\\n\\n    def test_should_create_with_required_field_only(self):\\n        \\\"\\\"\\\"Should create with only required is_valid field.\\\"\\\"\\\"\\n        result = ValidationResult(is_valid=False)\\n\\n        assert result.is_valid is False\\n        assert result.code is None\\n        assert result.error is None\\n        assert result.class_name is None\\n\\n    def test_should_serialize_to_dict(self):\\n        \\\"\\\"\\\"Should serialize to dictionary correctly.\\\"\\\"\\\"\\n        result = ValidationResult(\\n            is_valid=True,\\n            code=\\\"test code\\\",\\n            class_name=\\\"TestComponent\\\",\\n        )\\n\\n        data = result.model_dump()\\n\\n        assert data[\\\"is_valid\\\"] is True\\n        assert data[\\\"code\\\"] == \\\"test code\\\"\\n        assert data[\\\"class_name\\\"] == \\\"TestComponent\\\"\\n        assert data[\\\"error\\\"] is None\\n\\n    def test_should_deserialize_from_dict(self):\\n        \\\"\\\"\\\"Should deserialize from dictionary correctly.\\\"\\\"\\\"\\n        data = {\\n            \\\"is_valid\\\": False,\\n            \\\"error\\\": \\\"Test error\\\",\\n        }\\n\\n        result = ValidationResult(**data)\\n\\n        assert result.is_valid is False\\n        assert result.error == \\\"Test error\\\"\\n\\n\\nclass TestStepType:\\n    \\\"\\\"\\\"Tests for StepType literal type.\\\"\\\"\\\"\\n\\n    def test_should_define_all_expected_step_types(self):\\n        \\\"\\\"\\\"Should define all expected step types.\\\"\\\"\\\"\\n        expected_steps = [\\n            \\\"generating\\\",\\n            \\\"generation_complete\\\",\\n            \\\"extracting_code\\\",\\n            \\\"validating\\\",\\n            \\\"validated\\\",\\n            \\\"validation_failed\\\",\\n            \\\"retrying\\\",\\n        ]\\n\\n        # StepType is a Literal, we can check its args\\n        step_type_args = StepType.__args__\\n\\n        for step in expected_steps:\\n            assert step in step_type_args, f\\\"Missing step type: {step}\\\"\\n\\n    def test_step_types_should_be_strings(self):\\n        \\\"\\\"\\\"All step types should be strings.\\\"\\\"\\\"\\n        for step in StepType.__args__:\\n            assert isinstance(step, str)\\n\\n\\nclass TestSchemaIntegration:\\n    \\\"\\\"\\\"Integration tests for schema interactions.\\\"\\\"\\\"\\n\\n    def test_assistant_request_json_round_trip(self):\\n        \\\"\\\"\\\"Should survive JSON serialization round trip.\\\"\\\"\\\"\\n        original = AssistantRequest(\\n            flow_id=\\\"test-flow\\\",\\n            component_id=\\\"comp-1\\\",\\n            input_value=\\\"test\\\",\\n            max_retries=3,\\n        )\\n\\n        json_str = original.model_dump_json()\\n        restored = AssistantRequest.model_validate_json(json_str)\\n\\n        assert restored.flow_id == original.flow_id\\n        assert restored.component_id == original.component_id\\n        assert restored.input_value == original.input_value\\n        assert restored.max_retries == original.max_retries\\n\\n    def test_validation_result_json_round_trip(self):\\n        \\\"\\\"\\\"Should survive JSON serialization round trip.\\\"\\\"\\\"\\n        original = ValidationResult(\\n            is_valid=True,\\n            code=\\\"class Test: pass\\\",\\n            class_name=\\\"Test\\\",\\n        )\\n\\n        json_str = original.model_dump_json()\\n        restored = ValidationResult.model_validate_json(json_str)\\n\\n        assert restored.is_valid == original.is_valid\\n        assert restored.code == original.code\\n        assert restored.class_name == original.class_name\\n\\n\\nclass TestAssistantMessageLengthLimit:\\n    \\\"\\\"\\\"Tests for the operator-tunable prompt length cap.\\\"\\\"\\\"\\n\\n    def test_should_accept_a_prompt_at_the_default_limit(self):\\n        \\\"\\\"\\\"A prompt of exactly the default limit is valid.\\\"\\\"\\\"\\n        limit = get_settings_service().settings.assistant_max_message_length\\n        assert limit == 2000\\n\\n        request = AssistantRequest(flow_id=\\\"flow-1\\\", input_value=\\\"a\\\" * limit)\\n\\n        assert request.input_value is not None\\n        assert len(request.input_value) == limit\\n\\n    def test_should_reject_a_prompt_over_the_limit(self):\\n        \\\"\\\"\\\"A prompt past the limit is rejected with the limit in the message.\\\"\\\"\\\"\\n        limit = get_settings_service().settings.assistant_max_message_length\\n\\n        with pytest.raises(ValidationError) as exc_info:\\n            AssistantRequest(flow_id=\\\"flow-1\\\", input_value=\\\"a\\\" * (limit + 1))\\n\\n        assert str(limit) in str(exc_info.value)\\n\\n    def test_should_reject_an_overlong_headless_instruction(self):\\n        \\\"\\\"\\\"The headless route shares the same cap.\\\"\\\"\\\"\\n        limit = get_settings_service().settings.assistant_max_message_length\\n\\n        with pytest.raises(ValidationError):\\n            HeadlessAssistantRequest(instruction=\\\"a\\\" * (limit + 1))\\n\\n    def test_should_honor_a_raised_limit(self, monkeypatch):\\n        \\\"\\\"\\\"Raising LANGFLOW_ASSISTANT_MAX_MESSAGE_LENGTH widens both entry points.\\\"\\\"\\\"\\n        settings = get_settings_service().settings\\n        monkeypatch.setattr(settings, \\\"assistant_max_message_length\\\", 6000)\\n\\n        assert AssistantRequest(flow_id=\\\"flow-1\\\", input_value=\\\"a\\\" * 6000).input_value is not None\\n        assert HeadlessAssistantRequest(instruction=\\\"a\\\" * 6000).instruction is not None\\n\\n        with pytest.raises(ValidationError):\\n            AssistantRequest(flow_id=\\\"flow-1\\\", input_value=\\\"a\\\" * 6001)\\n\\n    def test_should_honor_a_lowered_limit(self, monkeypatch):\\n        \\\"\\\"\\\"Lowering the limit rejects prompts that the default would accept.\\\"\\\"\\\"\\n        settings = get_settings_service().settings\\n        monkeypatch.setattr(settings, \\\"assistant_max_message_length\\\", 100)\\n\\n        with pytest.raises(ValidationError):\\n            AssistantRequest(flow_id=\\\"flow-1\\\", input_value=\\\"a\\\" * 101)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_sessions_reset_endpoint.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b9ab47cabae613797e639de666fdc2b8ded06e98a185b2510d4fbd44cedba20\",\"content\":\"\\\"\\\"\\\"UC8 \u2014 POST /api/v1/agentic/sessions/reset endpoint.\\n\\nFrontend calls this on every \\\"new assistant session\\\" boundary:\\n    - panel mounts with a fresh session_id\\n    - user clicks the New session button\\n\\nThe endpoint:\\n    - is authenticated (any unauthenticated request \u2192 401, handled by\\n      the FastAPI dependency)\\n    - wipes the conversation buffer for the supplied session_id\\n    - wipes the user's registered components\\n\\nWe exercise the handler directly (not via TestClient) so the auth\\ndependency is bypassed via an injected ``current_user`` mock \u2014 mirrors\\nthe test style of ``test_files_endpoint.py``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport secrets\\nimport types\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom langflow.agentic.services.conversation_buffer import (\\n    ConversationBuffer,\\n    ConversationTurn,\\n)\\nfrom langflow.agentic.services.user_components import (\\n    get_user_components_dir,\\n    register_user_component,\\n)\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\nSAMPLE_CODE = (\\n    \\\"from lfx.custom import Component\\\\n\\\"\\n    \\\"from lfx.io import FloatInput, Output\\\\n\\\"\\n    \\\"from lfx.schema import Data\\\\n\\\"\\n    \\\"\\\\n\\\"\\n    \\\"class SumComponent(Component):\\\\n\\\"\\n    \\\"    inputs = [FloatInput(name='a'), FloatInput(name='b')]\\\\n\\\"\\n    \\\"    outputs = [Output(name='result', display_name='Sum', method='run')]\\\\n\\\"\\n    \\\"    def run(self) -> Data:\\\\n\\\"\\n    \\\"        return Data(data={'sum': (self.a or 0) + (self.b or 0)})\\\\n\\\"\\n)\\n\\n\\n@pytest.fixture\\ndef isolated_sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n    (tmp_path / \\\".fs_pepper\\\").write_bytes(secrets.token_bytes(32))\\n\\n    from lfx.components.files_and_knowledge.filesystem import FileSystemToolComponent\\n\\n    monkeypatch.setattr(\\n        FileSystemToolComponent,\\n        \\\"_resolve_auto_login\\\",\\n        lambda self: False,  # noqa: ARG005\\n    )\\n    return tmp_path\\n\\n\\n@pytest.fixture\\ndef fresh_conversation_buffer(monkeypatch: pytest.MonkeyPatch) -> ConversationBuffer:\\n    import langflow.agentic.services.conversation_buffer as module\\n\\n    buf = ConversationBuffer()\\n    monkeypatch.setattr(module, \\\"_singleton\\\", buf)\\n    return buf\\n\\n\\ndef _make_user(user_id: str = \\\"user-alice\\\"):\\n    \\\"\\\"\\\"A lightweight stand-in for the FastAPI CurrentActiveUser dependency.\\n\\n    The handler only reads ``current_user.id`` (string). A plain namespace\\n    keeps the test free of the SQLModel boilerplate.\\n    \\\"\\\"\\\"\\n    return types.SimpleNamespace(id=user_id)\\n\\n\\nclass TestResetSessionEndpointWipesComponents:\\n    async def test_should_delete_registered_components_for_calling_user(\\n        self,\\n        isolated_sandbox: Path,  # noqa: ARG002\\n        fresh_conversation_buffer: ConversationBuffer,  # noqa: ARG002\\n    ) -> None:\\n        register_user_component(\\n            user_id=\\\"user-alice\\\",\\n            class_name=\\\"SumComponent\\\",\\n            code=SAMPLE_CODE,\\n        )\\n\\n        from langflow.agentic.api.sessions_router import reset_session\\n\\n        result = await reset_session(\\n            current_user=_make_user(\\\"user-alice\\\"),\\n            session_id=\\\"agentic_xxx\\\",\\n        )\\n\\n        assert result[\\\"components_cleared\\\"] == 1\\n        components_dir = get_user_components_dir(user_id=\\\"user-alice\\\")\\n        assert components_dir is not None\\n        assert list(components_dir.iterdir()) == []\\n\\n    async def test_should_delete_conversation_buffer_for_session_id(\\n        self,\\n        isolated_sandbox: Path,  # noqa: ARG002 \u2014 fixture wires sandbox\\n        fresh_conversation_buffer: ConversationBuffer,\\n    ) -> None:\\n        fresh_conversation_buffer.push(\\n            \\\"user-alice\\\",\\n            \\\"agentic_xxx\\\",\\n            ConversationTurn(user=\\\"hi\\\", assistant=\\\"hello\\\"),\\n        )\\n\\n        from langflow.agentic.api.sessions_router import reset_session\\n\\n        await reset_session(\\n            current_user=_make_user(\\\"user-alice\\\"),\\n            session_id=\\\"agentic_xxx\\\",\\n        )\\n\\n        assert fresh_conversation_buffer.get_recent(\\\"user-alice\\\", \\\"agentic_xxx\\\") == []\\n\\n    async def test_should_not_touch_other_users_components(\\n        self,\\n        isolated_sandbox: Path,  # noqa: ARG002\\n        fresh_conversation_buffer: ConversationBuffer,  # noqa: ARG002\\n    ) -> None:\\n        register_user_component(\\n            user_id=\\\"user-alice\\\",\\n            class_name=\\\"SumComponent\\\",\\n            code=SAMPLE_CODE,\\n        )\\n        bob_path = register_user_component(\\n            user_id=\\\"user-bob\\\",\\n            class_name=\\\"BobSum\\\",\\n            code=SAMPLE_CODE,\\n        )\\n\\n        from langflow.agentic.api.sessions_router import reset_session\\n\\n        await reset_session(\\n            current_user=_make_user(\\\"user-alice\\\"),\\n            session_id=\\\"agentic_xxx\\\",\\n        )\\n\\n        # Bob's file untouched.\\n        assert bob_path.exists()\\n\\n    async def test_should_not_touch_other_sessions_conversation_buffer(\\n        self,\\n        isolated_sandbox: Path,  # noqa: ARG002\\n        fresh_conversation_buffer: ConversationBuffer,\\n    ) -> None:\\n        fresh_conversation_buffer.push(\\n            \\\"user-alice\\\",\\n            \\\"agentic_xxx\\\",\\n            ConversationTurn(user=\\\"hi\\\", assistant=\\\"ack\\\"),\\n        )\\n        fresh_conversation_buffer.push(\\n            \\\"user-alice\\\",\\n            \\\"agentic_yyy\\\",\\n            ConversationTurn(user=\\\"other\\\", assistant=\\\"other-ack\\\"),\\n        )\\n\\n        from langflow.agentic.api.sessions_router import reset_session\\n\\n        await reset_session(\\n            current_user=_make_user(\\\"user-alice\\\"),\\n            session_id=\\\"agentic_xxx\\\",\\n        )\\n\\n        # The other session is preserved.\\n        assert len(fresh_conversation_buffer.get_recent(\\\"user-alice\\\", \\\"agentic_yyy\\\")) == 1\\n\\n\\nclass TestResetSessionEndpointShape:\\n    async def test_should_accept_missing_session_id(\\n        self,\\n        isolated_sandbox: Path,  # noqa: ARG002\\n        fresh_conversation_buffer: ConversationBuffer,  # noqa: ARG002\\n    ) -> None:\\n        register_user_component(\\n            user_id=\\\"user-alice\\\",\\n            class_name=\\\"SumComponent\\\",\\n            code=SAMPLE_CODE,\\n        )\\n\\n        from langflow.agentic.api.sessions_router import reset_session\\n\\n        # session_id=None still wipes components (the \\\"fresh mount with\\n        # a brand new id\\\" scenario fires before any turns are logged \u2014\\n        # the conversation buffer has nothing to clear).\\n        result = await reset_session(\\n            current_user=_make_user(\\\"user-alice\\\"),\\n            session_id=None,\\n        )\\n\\n        assert result[\\\"components_cleared\\\"] == 1\\n\\n    async def test_should_return_zero_counts_when_nothing_to_clear(\\n        self,\\n        isolated_sandbox: Path,  # noqa: ARG002\\n        fresh_conversation_buffer: ConversationBuffer,  # noqa: ARG002\\n    ) -> None:\\n        from langflow.agentic.api.sessions_router import reset_session\\n\\n        result = await reset_session(\\n            current_user=_make_user(\\\"user-alice\\\"),\\n            session_id=\\\"agentic_never-used\\\",\\n        )\\n\\n        assert result[\\\"components_cleared\\\"] == 0\\n        # Conversation history clear is silent \u2014 endpoint reports the\\n        # components count, not a history count (history is unbounded\\n        # in shape; reporting a number is meaningless).\\n        assert \\\"ok\\\" in result.get(\\\"status\\\", \\\"\\\").lower() or result.get(\\\"status\\\") == \\\"ok\\\"\\n\"}]}";
